/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A55 staging patch: exact frozen manifest informative–insure (80 entries). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('informative','Informative 由 inform 加形容词后缀 -ative 构成，形容能提供大量有用信息的内容或材料。',C('informative.s1','学习与资料','The museum’s short video was informative, explaining how the bridge was built and why it survived the flood.','博物馆的短片信息丰富，解释了桥梁的建造过程以及它为何能在洪水中幸存。','The museum’s short video was informative / explaining how the bridge was built / and why it survived the flood.','informative 作表语，表示视频提供有用信息；explaining 补充其内容。','短片说明建造过程和存续原因，提供了有用知识。'),M('The video was informative because it gave viewers no facts about the bridge or the flood.','The video was uninformative because it gave viewers no facts about the bridge or the flood.','没有提供事实的信息不能称 informative。','word-choice'),[Q('informative',1,1,'An informative guide is one that?','provides useful information','avoids explaining the subject','is too difficult to reach','informative 指内容能提供有用信息。'),Q('informative',2,1,'Why was the museum video informative?','it explained the bridge’s construction and survival','it showed only a blank screen','it hid every fact from visitors','视频解释了桥梁细节。'),Q('informative',3,1,'Which item would be most informative for a visitor?','a clear display explaining the site’s history','an unlabeled empty frame','a ticket with no directions or details','介绍历史的展板有助于了解信息。'),Q('informative',4,1,'Informative is closest in meaning to?','educational and useful','inaccurate and misleading','silent and empty','informative 表示有信息价值。')]);
P('informed','Informed 由 inform 加 -ed 构成，可形容了解相关事实的人，也可描述基于充分了解作出的决定。',[C('informed.s1','知识与判断','After reading the safety report and asking the engineer questions, Mei felt informed enough to choose a suitable helmet.','读过安全报告并向工程师提问后，梅觉得自己了解得足够充分，可以选择合适的头盔。','After reading the safety report and asking the engineer questions / Mei felt informed enough / to choose a suitable helmet.','informed 描写掌握相关事实的人；enough to 引出她据此能够做的决定。','阅读报告和询问专家让她获得了相关知识。'),C('informed.s2','决策与依据','The board made an informed decision to delay construction after reviewing the flood maps and engineering estimates.','董事会审阅洪水地图和工程估算后，作出推迟施工的知情决定。','The board made an informed decision to delay construction / after reviewing the flood maps and engineering estimates.','informed 修饰 decision，表示决定依据充分了解的事实；after 引出审议过程。','审阅相关资料后再决定，体现基于事实的判断。')],M('The board made an informed decision without reading the report, checking the data, or learning the relevant facts.','The board made an uninformed decision without reading the report, checking the data, or learning the relevant facts.','不了解事实作出的决定不能称 informed。','word-choice'),[Q('informed',1,1,'An informed person?','knows the relevant facts','has deliberately avoided all information','is unable to learn anything','s1 指了解相关事实的。'),Q('informed',2,2,'An informed decision is based on?','a proper understanding of the facts','a random guess made without evidence','a rumor that has not been checked','s2 指在充分了解基础上作出的决定。'),Q('informed',3,1,'How did Mei become informed about helmets?','she read the report and asked an engineer','she ignored every safety source','she chose only by color','了解资料并请教专家使她知情。'),Q('informed',4,2,'Why was the board’s delay an informed decision?','it reviewed flood maps and engineering estimates first','it decided before seeing any information','it chose a date by chance','先审核资料使决定有事实依据。')]);
P('infrared','Infrared 由拉丁语 infra“在下方”与 red“红色”构成，可作名词指红光之外、肉眼不可见的光，也可作形容词描述使用该波段的设备或辐射。',[C('infrared.s1','光谱与探测','The sensor detected infrared from the warm roof even though the building looked dark to the naked eye.','尽管肉眼看去建筑一片漆黑，传感器仍探测到了温暖屋顶发出的红外线。','The sensor detected infrared from the warm roof / even though the building looked dark / to the naked eye.','infrared 作名词指肉眼看不见的红外光；even though 对照传感器读数和视觉。','传感器检测到不可见波段的热辐射。'),C('infrared.s2','设备与遥感','The technician used an infrared camera to find heat escaping around the window frame.','技师使用红外摄像机查找从窗框周围散失的热量。','The technician used an infrared camera / to find heat escaping / around the window frame.','infrared 作形容词修饰 camera，表示设备利用红外光工作；to find 表示用途。','红外相机能显示窗边热量变化。')],M('The technician used an infrared camera that detected only ordinary visible red light.','The technician used an infrared camera that detected wavelengths beyond visible red.','红外线位于可见红光之外，而非普通可见红光。','confusable'),[Q('infrared',1,1,'Infrared is a kind of light that?','lies beyond red and cannot be seen by human eyes','is brighter than every visible color','is identical to ordinary green light','s1 指红光之外的不可见波段。'),Q('infrared',2,2,'An infrared camera is designed to?','use or detect infrared radiation','record only visible sound waves','measure distance in inches','s2 形容使用红外波段的设备。'),Q('infrared',3,1,'Why could the sensor detect the warm roof in darkness?','it detected infrared radiation','it made the roof emit visible green light','it measured the roof’s legal status','温热物体会发出红外辐射。'),Q('infrared',4,2,'Which tool could reveal heat loss around a window?','an infrared camera','a paper ruler','a visible-light-only label','红外相机可显示热量分布。')]);
P('infrasound','Infrasound 由 infra-“低于”与 sound“声音”组合，指频率低于人耳通常可听范围（约20赫兹以下）的声波。',C('infrasound.s1','声音与频率','Elephants can communicate over long distances using infrasound that people cannot hear.','大象可以利用人类听不到的次声进行远距离交流。','Elephants can communicate over long distances / using infrasound / that people cannot hear.','infrasound 指低于人耳可听频率范围的声波；that 从句补充其特点。','人类听不到这些低频声波。'),M('The detector recorded infrasound at 30,000 hertz, far above the usual upper limit of human hearing.','The detector recorded ultrasound at 30,000 hertz, far above the usual upper limit of human hearing.','远高于人耳听觉上限的频率属于超声，而非次声。','confusable'),[Q('infrasound',1,1,'Infrasound consists of sound waves?','below the range of human hearing','above every radio frequency','inside the visible light spectrum','次声频率低于人耳可听范围。'),Q('infrasound',2,1,'Roughly what frequency range is associated with infrasound?','below about 20 hertz','around 20,000 hertz and higher','exactly 2,000 inches','通常约低于20赫兹。'),Q('infrasound',3,1,'Why might people fail to hear elephant infrasound?','its frequency is too low for human hearing','it is a type of visible light','elephants communicate only in silence','次声频率低到人耳听不见。'),Q('infrasound',4,1,'Which word is the opposite frequency direction from infrasound?','ultrasound','infrared','insulation','ultrasound 指高于听觉范围的超声。')]);
P('infrequent','Infrequent 由 in- 与 frequent“频繁的”构成，形容某事发生得很少、不常见。',C('infrequent.s1','发生频率','Because the road is closed only during rare storms, service interruptions are infrequent in this region.','由于只有罕见风暴时道路才会关闭，这个地区的服务中断并不常见。','Because the road is closed only during rare storms / service interruptions are infrequent / in this region.','infrequent 作表语，表示中断很少发生；because 说明其频率低的原因。','只有罕见风暴才会导致中断。'),M('Train delays were infrequent even though they happened every day on every route.','Train delays were frequent because they happened every day on every route.','每天每条线路都延误，不符合 infrequent。','word-choice'),[Q('infrequent',1,1,'An infrequent event happens?','only rarely','every few seconds','more often than anything else','infrequent 表示不常发生。'),Q('infrequent',2,1,'Why were service interruptions infrequent?','the road closed only during rare storms','the road closed every morning','the service had stopped permanently','罕见风暴才封路，说明中断少见。'),Q('infrequent',3,1,'Which event is infrequent?','a comet visible in a particular region once in many years','a clock ticking each second','a daily bus departure','多年才发生的现象属于不常见。'),Q('infrequent',4,1,'Infrequent is closest in meaning to?','rare','constant','informed','infrequent 与 rare 接近。')]);
P('infrequently','Infrequently 由 infrequent 加 -ly 构成，表示很少发生、不经常地。',C('infrequently.s1','习惯与频次','The rural clinic opens on Sundays infrequently, so patients check its monthly schedule before traveling.','这家乡村诊所很少在星期日开放，因此病人出发前会查看月度安排。','The rural clinic opens on Sundays infrequently / so patients check its monthly schedule / before traveling.','infrequently 修饰 opens，表示开放次数少；so 引出病人查看安排的做法。','星期日开放不是常规服务。'),M('The clinic opens infrequently on Sundays, meaning that it opens every Sunday without exception.','The clinic opens frequently on Sundays, meaning that it opens every Sunday without exception.','每个星期日都开放是经常发生，而非 infrequently。','word-choice'),[Q('infrequently',1,1,'If a clinic opens infrequently, it opens?','on rare occasions','every day without interruption','only when it is permanently closed','infrequently 表示很少。'),Q('infrequently',2,1,'Why check the clinic’s schedule before traveling?','Sunday openings happen only rarely','the clinic is open every day','the schedule has no information','星期日不常开放，需提前查安排。'),Q('infrequently',3,1,'Which sentence uses infrequently correctly?','The ferry runs infrequently during winter storms.','The ferry runs infrequently every minute all day.','The ferry infrequently is a harbor.','副词表示冬季风暴期间航次很少。'),Q('infrequently',4,1,'Infrequently is the adverb form of?','infrequent','infrequente','infrequencyless','infrequently 由形容词 infrequent 加 -ly 构成。')]);
P('infuriate','Infuriate 与 Latin furia“狂怒”相关，作动词表示使某人极其愤怒。',C('infuriate.s1','争执与情绪','It infuriated the residents when the contractor blocked their only entrance without warning.','承包商没有预先通知就堵住居民唯一的出入口，这让他们勃然大怒。','It infuriated the residents / when the contractor blocked their only entrance / without warning.','infuriate 是及物动词，表示使人狂怒；when 从句交代激怒原因。','唯一通道被无预警封堵，导致强烈愤怒。'),M('The unexplained blockade infuriated the residents, meaning it made them entirely calm and pleased.','The unexplained blockade angered the residents, making them extremely upset.','infuriate 表示激怒，不是让人平静高兴。','meaning'),[Q('infuriate',1,1,'To infuriate someone is to make them?','furiously angry','slightly sleepy','well informed','infuriate 意为使狂怒。'),Q('infuriate',2,1,'What infuriated the residents?','their only entrance was blocked without warning','the contractor opened a second entrance','the residents received advance notice','堵住唯一通道且无预警使居民愤怒。'),Q('infuriate',3,1,'Which action could infuriate a customer?','charging a fee that was never disclosed','apologizing and correcting an error','providing the promised service','隐瞒费用可能激怒顾客。'),Q('infuriate',4,1,'Infuriate is stronger than merely?','annoy','inform','inhabit','infuriate 表示极强的愤怒。')]);
P('ingeniously','Ingeniously 由 ingenious 加副词后缀 -ly 构成，表示以富有创意的巧思解决问题。',C('ingeniously.s1','设计与解题','The mechanic ingeniously used a bicycle brake cable to open the jammed latch until a replacement part arrived.','维修工巧妙地用自行车刹车线打开卡住的插销，直到替换零件送到。','The mechanic ingeniously used a bicycle brake cable / to open the jammed latch / until a replacement part arrived.','ingeniously 修饰 used，强调解决办法巧妙而有创意；to 表示使用目的。','借用刹车线解决插销问题显示创造性。'),M('The mechanic ingeniously solved the problem by trying no alternatives and leaving the latch jammed.','The mechanic ingeniously solved the problem by adapting a cable to open the latch.','没有尝试解决、仍让插销卡住，不是巧妙地解决问题。','word-choice'),[Q('ingeniously',1,1,'To solve a problem ingeniously is to solve it?','with original cleverness','by repeating a failed method','without noticing the problem','ingeniously 表示巧妙地。'),Q('ingeniously',2,1,'Why was the mechanic’s repair ingenious?','he adapted an available cable to open the latch','he waited and made no attempt','he broke the latch further','巧用现有零件解决卡锁很有创意。'),Q('ingeniously',3,1,'Which action is done ingeniously?','using a simple household item to devise a safe repair','discarding every tool and making no plan','copying an unsuccessful attempt exactly','灵活改造现有工具体现巧思。'),Q('ingeniously',4,1,'Ingeniously is related to which adjective?','ingenious','ingenuous','infrequent','ingeniously 来自 ingenious。')]);
P('ingenuous','Ingenuous 来自拉丁语 ingenuus“自由出生的、坦率的”，形容天真坦率、没有隐藏动机的。',C('ingenuous.s1','诚实与坦率','The ingenuous child admitted that she had broken the vase instead of inventing an excuse.','那个天真坦率的孩子承认自己打碎了花瓶，而没有编造借口。','The ingenuous child admitted / that she had broken the vase / instead of inventing an excuse.','ingenuous 修饰 child，表示坦率真诚；instead of 对比坦白与编借口。','直接承认过失体现天真坦率。'),M('Her ingenuous answer concealed a carefully planned lie and several hidden motives.','Her ingenuous answer was open and honest, without a hidden motive.','蓄意隐瞒谎言与 ingenuous 的坦率义相反。','word-choice'),[Q('ingenuous',1,1,'An ingenuous person is?','innocently frank and without hidden motives','clever at hiding a dishonest plan','rarely seen in public','ingenuous 指天真坦率。'),Q('ingenuous',2,1,'Why did the child seem ingenuous?','she admitted breaking the vase without inventing an excuse','she blamed someone else with a false story','she concealed her actions carefully','坦白承认错误体现真诚。'),Q('ingenuous',3,1,'Which reply is ingenuous?','“I made the mistake, and I am sorry.”','“I know I did it, but I will blame someone else.”','“I will hide every fact from you.”','直接承认错误而无隐瞒是坦率的。'),Q('ingenuous',4,1,'Ingenuous is often confused with ingenious. Which means clever and inventive?','ingenious','ingenuous','informed','ingenious 表示聪明有创意；ingenuous 表示坦率天真。')]);
P('ingoing','Ingoing 由 in 与 going 组合，作形容词指进入或即将上任的，也可作名词指进入、迁入的行为。',[C('ingoing.s1','任职与交接','The ingoing director met with the outgoing director to review the hospital’s budget and current priorities.','即将上任的主任与即将离任的主任会面，审阅医院预算和当前重点。','The ingoing director met with the outgoing director / to review the hospital’s budget / and current priorities.','ingoing 修饰 director，表示即将进入该职位；outgoing 与之形成交接对比。','这位主任正要开始任职。'),C('ingoing.s2','进入与迁入','The building manager recorded each ingoing of new tenants so the security office could issue access cards.','大楼管理员记录每批新租户的迁入情况，以便保安办公室发放门禁卡。','The building manager recorded each ingoing of new tenants / so the security office / could issue access cards.','ingoing 作名词指进入或迁入；so 引出记录的用途。','新租户迁入是进入建筑的行为。')],M('The ingoing manager was described as leaving the position after a decade rather than beginning the role.','The outgoing manager was described as leaving the position after a decade.','离开职位的是 outgoing，而不是即将上任的 ingoing。','confusable'),[Q('ingoing',1,1,'An ingoing director is?','about to take up the position','leaving the position after a long term','unable to enter the building','s1 指即将上任的。'),Q('ingoing',2,2,'An ingoing of tenants refers to?','their act of moving into a building','their departure from the country','their monthly rent payment','s2 作名词指进入或迁入。'),Q('ingoing',3,1,'Which phrase contrasts with an ingoing manager?','an outgoing manager','an in-depth report','an informative notice','ingoing 与 outgoing 对比。'),Q('ingoing',4,2,'Why record each ingoing of tenants?','to track arrivals and prepare access cards','to record their departure from the city','to measure the hallway in inches','迁入记录便于办理门禁。')]);
P('ingot','Ingot 是英语中用于金属铸块的词，其更深层词源说法不确定；现代指待进一步加工的金属条块。',C('ingot.s1','冶金与加工','The foundry poured molten steel into a mold and let it cool into an ingot for later rolling.','铸造厂把熔融钢水倒入模具，冷却成金属锭后再进行轧制。','The foundry poured molten steel into a mold / and let it cool into an ingot / for later rolling.','ingot 指待后续加工的金属块；into 引出冷却后形成的形态。','钢水冷却成块状原料，供后续轧制。'),M('The foundry called the finished metal ingot a liquid because it remained molten and had no solid shape.','The foundry called the cooled metal block an ingot, ready for later working.','已冷却、成块的金属不是液体。','word-choice'),[Q('ingot',1,1,'An ingot is?','a bar or block of metal ready for later working','a thin sheet of paper','a unit of sound frequency','ingot 指金属锭。'),Q('ingot',2,1,'What happens before a steel ingot is rolled?','molten steel cools into a solid block','the finished sheet melts into liquid','the metal is dissolved in water','金属先冷却成块，再进一步加工。'),Q('ingot',3,1,'Which object is an ingot?','a cast block of gold prepared for shaping','a gold-colored cloth ribbon','a chart showing infrared light','铸成的金属块符合 ingot。'),Q('ingot',4,1,'Why does a foundry cast metal into ingots?','the blocks can be stored and worked later','the blocks are already finished clothing','the metal must remain liquid forever','金属锭便于储存和后续加工。')]);
P('inhabitable','Inhabitable 由 inhabit 与 -able 构成，表示环境适合人或动物居住。',C('inhabitable.s1','居住环境','Engineers confirmed that the repaired cabin was inhabitable after they restored the roof, heat, and clean water.','工程师修好屋顶、供暖和清洁供水后，确认这间小屋适合居住。','Engineers confirmed that the repaired cabin was inhabitable / after they restored the roof, heat, and clean water.','inhabitable 作表语，表示适宜居住；after 引出达到居住条件的修复工作。','屋顶、供暖和水源恢复后，小屋可供居住。'),M('The cabin was inhabitable even though its roof had collapsed and there was no heat or clean water.','The cabin was uninhabitable because its roof had collapsed and there was no heat or clean water.','屋顶坍塌且没有供暖和饮水说明环境不适合居住。','word-choice'),[Q('inhabitable',1,1,'An inhabitable building is?','fit for people or animals to live in','already empty of every resident','impossible to enter under any condition','inhabitable 表示适宜居住。'),Q('inhabitable',2,1,'Why was the repaired cabin inhabitable?','it had a sound roof, heat, and clean water','it still lacked basic shelter and water','it was made entirely of molten steel','修复后具备基本居住条件。'),Q('inhabitable',3,1,'Which place is inhabitable?','a safe house with working water and shelter','a collapsed cave with toxic air','a frozen room with no protection','安全且有基本设施的住所可以居住。'),Q('inhabitable',4,1,'Inhabitable describes whether a place?','can suitably be lived in','is currently popular','is filled with residents right now','该词表示是否适宜居住，不表示当前有人住。')]);
P('inhabited','Inhabited 是 inhabit 的过去分词形容词，表示某地已有居民居住，而非空无一人。',C('inhabited.s1','人口与地域','The island is inhabited by a small fishing community that travels to the mainland once a week.','这座岛上住着一个小型渔村社群，他们每周乘船去一次大陆。','The island is inhabited by a small fishing community / that travels to the mainland / once a week.','be inhabited by 表示由某群体居住；that 从句补充居民的活动。','岛上有固定居民，因此并非无人岛。'),M('The island was inhabited, meaning no people lived there and the only buildings were empty.','The island was uninhabited, meaning no people lived there and the only buildings were empty.','无人居住的地方应说 uninhabited。','word-choice'),[Q('inhabited',1,1,'An inhabited island?','has people living on it','has never had a resident','cannot support any animal or plant','inhabited 表示有人居住。'),Q('inhabited',2,1,'The island is inhabited by fishers. Who lives there?','a fishing community','no one at all','only visitors who never stay','be inhabited by 指居住者。'),Q('inhabited',3,1,'Which place is inhabited?','a village with families living there','an abandoned empty house','a planet with no known residents','有居民生活的村庄是有人居住的。'),Q('inhabited',4,1,'Inhabited is different from inhabitable because inhabited means?','people already live there','it is merely fit to live there','it cannot be lived in','inhabited 指已有居民，inhabitable 指适宜居住。')]);
P('inhalation','Inhalation 由 inhale 加 -ation 构成，源自拉丁语 halare“呼吸”，指把空气、烟尘或蒸气吸入肺部的动作。',C('inhalation.s1','呼吸与医疗','The nurse asked the patient to take a slow inhalation through the nose before beginning the breathing test.','护士让病人在开始呼吸测试前用鼻子慢慢吸一口气。','The nurse asked the patient / to take a slow inhalation through the nose / before beginning the breathing test.','inhalation 指吸入空气的动作；to take 引出护士给出的指示。','鼻腔吸入一口气是 inhalation。'),M('The patient’s inhalation was the act of pushing air out of the lungs.','The patient’s exhalation was the act of pushing air out of the lungs.','呼出空气是 exhalation，而非 inhalation。','confusable'),[Q('inhalation',1,1,'Inhalation is the act of?','drawing air or another substance into the lungs','pushing air out of the lungs','measuring a person’s height','inhalation 指吸入。'),Q('inhalation',2,1,'What did the nurse ask the patient to take?','a slow breath in through the nose','a fast breath out through the mouth','a sip of water','吸入是把气体吸入肺中。'),Q('inhalation',3,1,'Which action is an inhalation?','breathing smoke into the lungs','breathing air out','holding a metal ingot','吸入烟雾属于 inhalation。'),Q('inhalation',4,1,'Inhalation is the opposite of?','exhalation','insulation','inhabitation','exhalation 表示呼出。')]);
P('inherently','Inherently 由 inherent 加 -ly 构成，源自拉丁语 inhaerere“附着于”，表示某特征是事物固有、持久的一部分。',C('inherently.s1','性质与判断','The material is inherently brittle, so the designer added a flexible support rather than relying on the material alone.','这种材料天生易脆，因此设计师加了柔性支撑，而不只依靠材料本身。','The material is inherently brittle / so the designer added a flexible support / rather than relying on the material alone.','inherently 修饰 brittle，表示脆性是材料固有属性；so 引出设计应对。','材料的易脆是其本身固有性质。'),M('The material is inherently flexible even though flexibility was added only by an external support.','The material is not inherently flexible; the support adds flexibility to it.','外部支撑提供的灵活性不是材料自身固有的。','meaning'),[Q('inherently',1,1,'A quality that exists inherently is?','a natural and lasting part of something','added only by a temporary external device','present once by accident','inherently 表示固有地。'),Q('inherently',2,1,'Why did the designer support the brittle material?','its brittleness was a built-in property','the material was naturally unbreakable','the support had already disappeared','脆性是材料固有特征，需要辅助设计。'),Q('inherently',3,1,'Which quality is inherently present?','a natural characteristic of the material itself','a temporary color painted onto it','a label attached at the factory','自身天然具备的特征是 inherently present。'),Q('inherently',4,1,'Inherently is closest in meaning to?','by its nature','in exchange','by mistake','inherently 意为本质上、固有地。')]);
P('inherited','Inherited 是 inherit 的过去分词形容词，指通过生物遗传、法律或习俗从上一代获得的。',C('inherited.s1','遗传与传承','The inherited recipe had passed through three generations, with each cook adding a note about the family’s preferred spices.','这份代代相传的食谱已经传了三代，每位厨师都会添上家人偏爱的香料说明。','The inherited recipe had passed through three generations / with each cook adding a note / about the family’s preferred spices.','inherited 修饰 recipe，表示从前一代传承而来；with 短语说明每代的补充。','食谱经多代传承，体现习俗上的继承。'),M('The inherited house was purchased yesterday by a buyer who had no family or legal connection to its former owner.','The inherited house was passed to the new owner through family or legal succession.','单纯购买不是 inherited。','word-choice'),[Q('inherited',1,1,'An inherited object is one that?','was passed down from an earlier generation','was made just now by its current owner','cannot be owned by anyone','inherited 表示从上一代承继。'),Q('inherited',2,1,'A family recipe may be inherited through?','custom and generations of use','a one-time accidental discovery only','an unrelated store receipt','食谱可经家庭传统代代相传。'),Q('inherited',3,1,'Which item is inherited?','a property transferred to someone by a relative’s will','a chair bought at a shop this morning','a tool borrowed for one afternoon','通过遗嘱获得的房产是继承所得。'),Q('inherited',4,1,'Inherited can refer to a trait passed by?','biology or legal and family custom','a random online advertisement','a temporary loan','可指遗传或法律、习俗传承。')]);
P('inhibition','Inhibition 来自拉丁语 inhibitio“阻止”，可指使人拘谨的心理障碍，也可指减慢或阻止某一过程的作用。',[C('inhibition.s1','社交与拘束','A fear of making mistakes created an inhibition that kept Sam from asking questions during the seminar.','害怕犯错形成的心理拘束使山姆在研讨会上不敢提问。','A fear of making mistakes created an inhibition / that kept Sam / from asking questions during the seminar.','inhibition 指阻止自然行为的心理拘束；that 从句说明其影响。','害怕犯错抑制了提问行为。'),C('inhibition.s2','生物过程','The drug’s inhibition of the enzyme slowed the reaction, giving researchers time to measure each stage.','药物对该酶的抑制减慢了反应，使研究人员有时间测量每个阶段。','The drug’s inhibition of the enzyme slowed the reaction / giving researchers time / to measure each stage.','inhibition of 表示减慢或阻止某过程；giving 补充减速带来的结果。','药物抑制酶活性，降低反应速度。')],M('The enzyme inhibition accelerated the reaction and made it proceed faster.','The enzyme inhibition slowed the reaction by reducing the enzyme’s activity.','inhibition 是抑制、减慢，不是加速。','confusable'),[Q('inhibition',1,1,'A social inhibition may?','make someone embarrassed and hold back natural behavior','make someone speak without any restraint','prove that a person is in charge','s1 指拘束行为的心理障碍。'),Q('inhibition',2,2,'Enzyme inhibition can?','slow or prevent a biological process','make every reaction faster','turn an enzyme into an ingot','s2 指抑制某过程。'),Q('inhibition',3,1,'Why did Sam remain quiet?','an inhibition made him afraid to ask questions','he had no questions and felt confident','the seminar was held in an infrasound chamber','心理拘束使他不敢发问。'),Q('inhibition',4,2,'A drug’s inhibition of an enzyme means it?','reduces or blocks the enzyme’s activity','adds new enzyme activity','measures the enzyme’s age','inhibition 指减少或阻断活性。')]);
P('inhibitor','Inhibitor 由 inhibit 加表示人或物的后缀 -or 构成，可指降低酶、反应或生物活性的化学物质，也可泛指阻碍发展的因素。',[C('inhibitor.s1','化学与酶','The enzyme inhibitor reduced the reaction rate without destroying the enzyme, allowing the team to study its effect.','这种酶抑制剂在没有破坏酶的情况下减慢了反应速度，使团队能够研究其作用。','The enzyme inhibitor reduced the reaction rate / without destroying the enzyme / allowing the team to study its effect.','inhibitor 指降低酶或反应活性的化学物质；without 表示抑制但未破坏。','反应速率下降体现酶抑制作用。'),C('inhibitor.s2','发展与障碍','High rent became an inhibitor of the small business’s growth, leaving little money for new equipment.','高额租金成了小企业发展的阻碍，使它几乎没有资金购买新设备。','High rent became an inhibitor of the small business’s growth / leaving little money / for new equipment.','inhibitor 可比喻阻碍发展的因素；of 指受阻的成长。','租金挤占发展资金，妨碍企业扩张。')],M('The inhibitor accelerated the enzyme reaction and encouraged the business to expand rapidly.','The inhibitor slowed the enzyme reaction and held back the business’s growth.','inhibitor 指抑制或阻碍因素，而非促进因素。','confusable'),[Q('inhibitor',1,1,'A chemical inhibitor can?','reduce the activity of an enzyme or reaction','increase every reaction without limit','serve as a unit of length','s1 指抑制活性的化学物质。'),Q('inhibitor',2,2,'High rent was an inhibitor of growth because it?','held back expansion by taking funds','provided unlimited money for new equipment','had no effect on the business','s2 指阻碍发展的因素。'),Q('inhibitor',3,1,'Which item could be an enzyme inhibitor?','a chemical that reduces the enzyme’s activity','a substance that makes the enzyme work faster','a tool that measures a building','降低酶活性的化学物质是抑制剂。'),Q('inhibitor',4,2,'A barrier that holds back progress is an inhibitor in?','a general figurative sense','a sense limited to measuring enzymes','a sense meaning a public ceremony','inhibitor 可泛指阻碍发展之物。')]);
P('inhospitable','Inhospitable 由 in- 与 hospitable“好客的”构成，可形容不适合生存的严酷环境，也可形容冷淡、不欢迎来访者的人或地方。',[C('inhospitable.s1','环境与生存','The research station sits in an inhospitable desert where water is scarce and temperatures shift sharply at night.','研究站位于荒凉严酷的沙漠中，那里水源稀少，夜间温度骤变。','The research station sits in an inhospitable desert / where water is scarce / and temperatures shift sharply at night.','inhospitable 描写环境严酷、难以生存；where 从句列出恶劣条件。','缺水和温差使沙漠不宜居住。'),C('inhospitable.s2','待客与态度','The hosts were inhospitable to the visiting volunteers, refusing to offer directions or a place to wait.','主人对来访志愿者态度冷淡，既不愿指路，也不让他们等候。','The hosts were inhospitable to the visiting volunteers / refusing to offer directions / or a place to wait.','inhospitable to 描述不欢迎来访者；refusing 说明冷淡表现。','拒绝提供基本帮助体现不友善待客。')],M('The hosts were inhospitable because they warmly welcomed every visitor and offered help.','The hosts were hospitable because they warmly welcomed every visitor and offered help.','热情欢迎来访者说明好客，不是冷淡排斥。','word-choice'),[Q('inhospitable',1,1,'An inhospitable landscape is?','harsh and offering little comfort or chance of survival','easy to live in with plentiful water','a room with an inbuilt heater','s1 指荒凉严酷的环境。'),Q('inhospitable',2,2,'An inhospitable host may?','treat visitors coldly and refuse to welcome them','greet every guest warmly','help guests find a place to stay','s2 指不友好、不欢迎。'),Q('inhospitable',3,1,'Why is the desert inhospitable?','water is scarce and conditions are severe','it has abundant water and steady mild weather','it contains a comfortable guest room','恶劣条件使沙漠难以生存。'),Q('inhospitable',4,2,'Which behavior is inhospitable?','refusing a visitor basic directions and a place to wait','offering a guest water and help','giving a visitor a warm welcome','拒绝基本帮助体现冷淡。')]);
P('inhumane','Inhumane 由 in- 与 humane“有人道精神的”构成，形容残酷且无视人的尊严与福祉的行为或条件。',C('inhumane.s1','福利与尊严','The report called the overcrowded shelter conditions inhumane because families had no clean water or private space.','报告称拥挤收容所的条件不人道，因为家庭没有清洁饮水或私人空间。','The report called the overcrowded shelter conditions inhumane / because families had no clean water / or private space.','inhumane 作补语评价条件残酷、缺乏人道；because 给出理由。','没有饮水和隐私的拥挤环境忽视人的基本尊严。'),M('The report described the shelter as inhumane because every family had clean water, space, and respectful care.','The report described the shelter as humane because every family had clean water, space, and respectful care.','提供清洁饮水和尊重照护符合 humane，不是 inhumane。','word-choice'),[Q('inhumane',1,1,'Inhumane treatment is?','cruel and lacking respect for human dignity','kind and attentive to people’s needs','a detailed historical account','inhumane 指不人道。'),Q('inhumane',2,1,'Why were the shelter conditions called inhumane?','families lacked clean water and private space','every family received careful support','the shelter was well supplied','基本需求得不到保障，说明条件不人道。'),Q('inhumane',3,1,'Which action is inhumane?','deliberately denying a person basic care','providing medical help respectfully','protecting someone from danger','拒绝基本照护是残酷行为。'),Q('inhumane',4,1,'Inhumane is the opposite of?','humane','inhabited','ingenious','humane 表示有人道精神的。')]);
P('inhumanity','Inhumanity 由 inhuman 加 -ity 构成，指对人或动物表现出的残酷行为、缺乏人道。',C('inhumanity.s1','历史与暴行','The memorial documents the inhumanity of the forced march, including testimony from survivors and their families.','纪念馆记录了强迫行军中的暴行，包括幸存者及其家属的证词。','The memorial documents the inhumanity of the forced march / including testimony / from survivors and their families.','inhumanity 指残酷、不人道的行为；including 列举记录材料。','幸存者证词记录了对人的残忍对待。'),M('The memorial described the inhumanity of the march because every traveler was treated with kindness and given rest.','The memorial described the humanity of the march because every traveler was treated with kindness and given rest.','善待并安排休息体现人道，不是 inhumanity。','word-choice'),[Q('inhumanity',1,1,'Inhumanity is?','cruelty shown toward people or animals','careful kindness to those in need','the act of creating a new idea','该词指不人道或残酷行为。'),Q('inhumanity',2,1,'Why did the memorial document inhumanity?','to record cruel treatment during the forced march','to praise a harmless community festival','to measure the march’s distance in inches','记录强迫行军中的残酷对待。'),Q('inhumanity',3,1,'Which act shows inhumanity?','deliberately denying food to helpless captives','providing urgent care to an injured animal','welcoming travelers with shelter','故意虐待弱者体现残酷。'),Q('inhumanity',4,1,'Inhumanity is closest to?','cruelty','innovation','inhalation','inhumanity 与 cruelty 相近。')]);
P('iniquity','Iniquity 经拉丁语 iniquitas“ 不公、不平等”而来，指严重的不公正或邪恶行为。',C('iniquity.s1','正义与不公','The novel exposes the iniquity of the law that denied an entire neighborhood access to clean water.','小说揭露了一项法律的不义：它剥夺了整个社区获得清洁用水的机会。','The novel exposes the iniquity of the law / that denied an entire neighborhood / access to clean water.','iniquity 指严重不公或邪恶；that 从句具体说明法律的不公之处。','剥夺整个社区基本资源是不公正的。'),M('The historian called the fair law an iniquity because it treated every community equally and protected their rights.','The historian praised the fair law because it treated every community equally and protected their rights.','公平保护权利的法律不是严重不公。','word-choice'),[Q('iniquity',1,1,'An iniquity is?','gross injustice or a wicked act','a harmless mistake in spelling','a routine method for measuring sound','iniquity 指严重不公或恶行。'),Q('iniquity',2,1,'Why was the water law called an iniquity?','it denied a whole neighborhood access to clean water','it protected equal access for all residents','it installed a new public fountain','不公法律剥夺社区获得饮水的机会。'),Q('iniquity',3,1,'Which situation is an iniquity?','a rule that unfairly excludes a group from basic services','a fair rule applied equally','an accidental typo quickly corrected','严重且系统性的不公符合该词。'),Q('iniquity',4,1,'Iniquity is a strong word for?','injustice','inspiration','infrequency','iniquity 表示不义。')]);
P('injudicious','Injudicious 由 in- 与 judicious“明智的”构成，形容欠缺判断力、可能带来麻烦的做法。',C('injudicious.s1','判断与后果','It was injudicious to publish the unverified accusation before giving the employee a chance to respond.','在给员工回应机会之前就发布未经核实的指控，是不明智的做法。','It was injudicious / to publish the unverified accusation / before giving the employee a chance to respond.','injudicious 评价行动缺乏审慎判断；to 不定式说明该行动。','未经核实便公开指控，容易造成不公与麻烦。'),M('Publishing an unverified accusation after careful fact-checking and a fair response was injudicious.','Publishing an unverified accusation before fact-checking or hearing a response was injudicious.','经过核实并听取回应不是此处所述的不审慎行为。'),[Q('injudicious',1,1,'An injudicious decision is?','unwise and likely to cause trouble','carefully considered and sensible','impossible to understand','injudicious 表示不明智。'),Q('injudicious',2,1,'Why was publishing the accusation injudicious?','it was unverified and the employee had not responded','the facts had been checked and both sides heard','the report contained only public weather data','未核实且未听取回应就发布指控不审慎。'),Q('injudicious',3,1,'Which choice is injudicious?','spending the emergency budget before checking urgent needs','reviewing bids before choosing a contractor','waiting for evidence before making a claim','未评估需求就花完预算不明智。'),Q('injudicious',4,1,'Injudicious is closest to?','unwise','inherent','insectivorous','injudicious 与 unwise 相近。')]);
P('injunct','Injunct 来自拉丁语 injungere“施加、命令”，作法律动词表示以法令命令某人停止某行为或采取限制。',C('injunct.s1','法院与禁令','The judge moved to injunct the company from demolishing the historic wall until the preservation claim was heard.','法官决定下令禁止公司拆除历史围墙，直到遗产保护诉求得到审理。','The judge moved to injunct the company / from demolishing the historic wall / until the preservation claim was heard.','injunct A from doing 表示依法禁止 A 做某事；until 限定禁令期限。','法院暂时禁止拆除，体现法律限制义。'),M('The court injuncted the company to continue demolishing the wall, ordering it to stop the demolition.','The court enjoined the company from demolishing the wall, ordering it to stop the demolition.','命令停止拆除不是命令继续拆除；常规表达为 enjoin/injunct from。','collocation'),[Q('injunct',1,1,'To injunct a company is to?','restrain it by a legal order','praise it at an opening ceremony','make it a new legal entity','injunct 指以法律命令限制。'),Q('injunct',2,1,'Why did the judge injunct the demolition?','to stop it until the preservation claim was heard','to ensure the wall was removed immediately','to measure the wall’s height','禁令暂时阻止拆除。'),Q('injunct',3,1,'Which action could a court injunct?','a company’s planned demolition of protected property','a visitor’s quiet reading','a harmless change in office furniture','法院可依法禁止拆除受保护财产。'),Q('injunct',4,1,'In a legal context, injunct is related to?','an injunction','an ingot','an inhalation','injunct 与 injunction 同源。')]);
P('injunction','Injunction 来自拉丁语 injunctionem“命令、强加”，可指法官要求或禁止某行为的强制令，也可指坚决的告诫。',[C('injunction.s1','法律救济','The court issued an injunction requiring the landlord to restore heat while the tenants’ case proceeded.','法院发布强制令，要求房东在租户案件审理期间恢复供暖。','The court issued an injunction / requiring the landlord to restore heat / while the tenants’ case proceeded.','injunction 指法院强制命令；requiring 说明命令内容。','法院要求采取特定行动，属于司法强制令。'),C('injunction.s2','劝诫与指示','Her grandfather’s firm injunction to wear a helmet stayed with her long after she began cycling alone.','祖父坚决叮嘱她骑车戴头盔，这句话在她独自骑行后仍一直记在心里。','Her grandfather’s firm injunction to wear a helmet / stayed with her / long after she began cycling alone.','injunction 可指坚决的指示或告诫；to wear 说明叮嘱内容。','祖父强烈要求佩戴头盔，属于郑重告诫。')],M('The judge issued an injunction allowing the landlord to ignore the order and keep the heat turned off.','The judge issued an injunction requiring the landlord to restore the heat.','强制令要求房东恢复供暖，不是允许无视命令。'),[Q('injunction',1,1,'A court injunction is?','a judge’s order requiring or forbidding an action','a casual suggestion with no force','a new idea for a product','s1 指法院强制令。'),Q('injunction',2,2,'A firm injunction from a grandparent may be?','a strong instruction or warning','a court hearing transcript only','a metal block for later shaping','s2 指坚决的告诫。'),Q('injunction',3,1,'What did the judge’s injunction require?','the landlord had to restore heat','the landlord could ignore the tenants','the tenants had to demolish the building','法院命令要求恢复供暖。'),Q('injunction',4,2,'“Her injunction to wear a helmet” refers to?','her firm warning or instruction','a chemical that blocks an enzyme','a legal sentence for a crime','to wear a helmet 是坚决叮嘱内容。')]);
P('injurious','Injurious 由 injure 加 -ious 构成，源自拉丁语 injuria“伤害、不公”，形容可能损害健康、名誉或利益的。',C('injurious.s1','健康与利益','The review warned that prolonged exposure to the solvent could be injurious to workers’ health.','评估提醒，长期接触这种溶剂可能有害于工人健康。','The review warned / that prolonged exposure to the solvent / could be injurious to workers’ health.','injurious to 表示对……有害；that 从句说明风险。','长期接触可能损害健康。'),M('The report called the solvent injurious because it protected workers’ health and caused no harm.','The report called the solvent harmless because it protected workers’ health and caused no harm.','保护健康且不造成伤害，与 injurious 相反。','word-choice'),[Q('injurious',1,1,'An injurious substance is likely to?','harm health or someone’s interests','provide useful information','help a process continue','injurious 表示有害的。'),Q('injurious',2,1,'Why did the review warn about the solvent?','long exposure could damage workers’ health','the solvent was guaranteed to be harmless','the workers had already left the site','长期接触可能有害。'),Q('injurious',3,1,'Which comment could be injurious to a person’s reputation?','a damaging false accusation','a verified neutral biography','a private compliment','有害的虚假指控可能损害名誉。'),Q('injurious',4,1,'Injurious is closest in meaning to?','harmful','inspiring','inhabitable','injurious 与 harmful 相近。')]);
P('innermost','Innermost 由 inner 加最高级后缀 -most 构成，表示位置最深处的，也可指最私密、最深层的感情。',[C('innermost.s1','空间与层次','The sealed letter lay in the innermost compartment of the old case, beneath two layers of fabric.','密封信放在旧箱子最里面的隔层中，压在两层布下面。','The sealed letter lay in the innermost compartment / of the old case / beneath two layers of fabric.','innermost 修饰 compartment，表示最内层；beneath 进一步说明位置。','信件被放在箱子最深的隔层。'),C('innermost.s1','情感与隐私','In her diary, she finally described her innermost fears about leaving home for the first time.','她终于在日记里写下第一次离家时内心最深处的恐惧。','In her diary / she finally described her innermost fears / about leaving home for the first time.','innermost 修饰 fears，表示最深、最私密的情感；about 引出恐惧内容。','日记中表达的是不轻易说出的内心感受。')],M('The innermost compartment was the outer pocket attached to the outside of the case.','The outermost compartment was the pocket attached to the outside of the case.','外侧口袋是 outermost，不是 innermost。','confusable'),[Q('innermost',1,1,'The innermost compartment is?','the deepest or most central one','the pocket farthest outside','the final event in a process','s1 指最里面的。'),Q('innermost',2,1,'Innermost fears are?','the deepest and most private fears','public facts printed on a sign','fears that belong to another person','s2 指内心最深处的感受。'),Q('innermost',3,1,'Where would you find an object in the innermost pocket?','deep inside a bag','on the bag’s outer surface','under the road outside','innermost 表示最里面。'),Q('innermost',4,1,'Why might someone write innermost feelings in a diary?','they are private and deeply personal','they are the most public facts','they are instructions from a court','日记常记录私密情感。')]);
P('innocence','Innocence 来自拉丁语 innocentia“无害、无罪”，可指没有犯罪的清白，也可指缺少世故、天真的状态。',[C('innocence.s1','法律与清白','The court accepted new video evidence that supported the defendant’s innocence and overturned the conviction.','法院采纳了支持被告无罪的新视频证据，并撤销了定罪。','The court accepted new video evidence / that supported the defendant’s innocence / and overturned the conviction.','innocence 指未犯被指控罪行的状态；that 从句说明证据作用。','新证据支持被告无罪。'),C('innocence.s2','经验与天真','The child’s innocence showed in her belief that every adult always kept every promise.','孩子相信每个成年人都会信守承诺，这体现了她缺少世故的天真。','The child’s innocence showed / in her belief that every adult always kept every promise.','innocence 可指缺少世故经验；that 从句说明天真想法。','对成人一概信任显示天真。')],M('The jury established the defendant’s innocence by proving that he committed the crime.','The jury established the defendant’s guilt by proving that he committed the crime.','证明被告实施犯罪支持有罪，而非无罪。','word-choice'),[Q('innocence',1,1,'Legal innocence is?','the state of not being guilty of a crime','a willingness to commit a crime','the act of introducing a vaccine','s1 指无罪、清白。'),Q('innocence',2,2,'A child’s innocence may show as?','a lack of worldly experience','deep expertise in court procedure','a plan to deceive every adult','s2 指天真、不谙世故。'),Q('innocence',3,1,'What supports a defendant’s innocence?','evidence showing the person did not commit the crime','a witness proving the person committed it','a rumor without any evidence','证明未犯罪的证据支持清白。'),Q('innocence',4,2,'Why did the child trust every promise?','she was inexperienced and naive','she had conducted a legal trial','she was in charge of the adults','缺少世故经验使孩子天真。')]);
P('innovation','Innovation 由 innovate 加 -ion 构成，来自拉丁语 innovare“使更新”，可指引入新想法或方法的行为，也可指新点子、方法或装置本身。',[C('innovation.s1','流程与改进','The team’s innovation was to let residents report broken streetlights through a simple phone form.','团队的创新做法是让居民通过简易手机表格报告路灯故障。','The team’s innovation was / to let residents report broken streetlights / through a simple phone form.','innovation 指引入新方法的行为；to let 解释创新做法内容。','利用手机表格建立了新的报修流程。'),C('innovation.s2','产品与方法','The low-cost water sensor was an innovation that helped small farms detect leaks early.','这种低成本水传感器是一项创新，帮助小农场及早发现漏水。','The low-cost water sensor was an innovation / that helped small farms / detect leaks early.','innovation 可指新发明或方法；that 从句说明其用途。','水传感器是新装置，属于一项创新。')],M('The team called its innovation a new method, although it had copied the same process unchanged for decades.','The team called its innovation a new method because it introduced a different reporting process.','多年未变、照搬旧流程不构成新方法。','meaning'),[Q('innovation',1,1,'Innovation can mean?','the act of bringing in a new idea or method','the refusal to change any method','a long-standing family quarrel','s1 指创新行为。'),Q('innovation',2,2,'A new water sensor is an innovation because it is?','a new device or method','a routine court warning','a state of being asleep','s2 指新发明、新方法。'),Q('innovation',3,1,'Why was the phone form an innovation?','it created a new way for residents to report faults','it copied an old paper form without change','it prevented anyone from reporting faults','新流程改善了报修方式。'),Q('innovation',4,2,'Which item is an innovation?','a newly designed tool that detects leaks early','an unchanged procedure used for centuries','a rumor with no practical use','新型漏水检测工具属于创新。')]);
P('innovative','Innovative 由 innovate 加 -ive 构成，形容采用新想法、设计或方法的。',C('innovative.s1','产品与设计','The innovative lamp uses a small solar panel and a rechargeable battery to light paths after sunset.','这款创新灯具利用小型太阳能板和充电电池，在日落后照亮小路。','The innovative lamp uses a small solar panel and a rechargeable battery / to light paths / after sunset.','innovative 修饰 lamp，表示采用新设计；to light 引出设计用途。','太阳能板与可充电电池构成新颖设计。'),M('The company called its lamp innovative even though it copied an old design and added no new feature.','The company called its lamp conventional because it copied an old design and added no new feature.','没有新特征的仿制设计不算 innovative。','word-choice'),[Q('innovative',1,1,'An innovative design uses?','new ideas or methods','only familiar ideas with no change','a legal order','innovative 指采用新想法。'),Q('innovative',2,1,'What makes the solar lamp innovative?','it combines solar charging and a rechargeable battery for path lighting','it has no power source or new feature','it is an unchanged candle','新颖的能源组合支持照明。'),Q('innovative',3,1,'Which approach is innovative?','testing a new way to deliver clean water','repeating a failed process without changes','refusing to consider alternatives','尝试新方法解决问题是创新。'),Q('innovative',4,1,'Innovative is related to the noun?','innovation','innocence','inhibition','innovative 与 innovation 同源。')]);
P('innuendo','Innuendo 来自拉丁语 innuendo“暗示”，可作名词指含沙射影的间接暗示，也可作动词表示暗示令人不快的事。',[C('innuendo.s1','名誉与暗示','The columnist avoided innuendo and stated the documented conflict of interest directly.','专栏作者没有含沙射影，而是直接陈述有记录证明的利益冲突。','The columnist avoided innuendo / and stated the documented conflict of interest / directly.','innuendo 作名词指不直接明说的影射；and 对比含沙射影与直接陈述。','作者选择直接陈述证据，而非暗示。'),C('innuendo.s2','间接表达','During the interview, the spokesperson innuendoed that the missing funds had been mishandled but offered no evidence.','采访中，发言人暗示失踪资金遭到不当处理，却没有提供证据。','During the interview / the spokesperson innuendoed that the missing funds had been mishandled / but offered no evidence.','innuendo 作动词表示间接暗示；that 从句引出暗示内容。','没有直接明说而影射资金被处理不当。')],M('The speaker used innuendo by directly stating every accusation with clear evidence and no suggestion.','The speaker avoided innuendo by stating the accusation directly and showing evidence.','清楚直接且有证据的陈述不是含沙射影。','word-choice'),[Q('innuendo',1,1,'An innuendo is?','an indirect hint, often damaging or suggestive','a fully documented statement made directly','a new scientific device','s1 指含沙射影。'),Q('innuendo',2,2,'To innuendo that funds were mishandled is to?','suggest it indirectly','prove it with a full audit','return the funds immediately','s2 作动词表示间接暗示。'),Q('innuendo',3,1,'Why did the columnist avoid innuendo?','they chose to state the documented conflict directly','they wanted to spread unsupported hints','they had no facts to report','直接陈述事实避免了影射。'),Q('innuendo',4,2,'Which statement uses innuendo as a verb?','She innuendoed that the manager had hidden the figures.','She filed an injunction with the court.','She measured the room in inches.','第一句用动词表示间接暗示。')]);
P('inoculate','Inoculate 来自拉丁语 inoculare“接种、嫁接”，可指给人或动物接种疫苗，也可指向培养物接入微生物或向群体逐渐引入观念。',[C('inoculate.s1','疫苗与防护','The clinic inoculated the volunteers against the virus before they began field work.','诊所在志愿者开始野外工作前为他们接种了预防该病毒的疫苗。','The clinic inoculated the volunteers against the virus / before they began field work.','inoculate someone against something 表示给某人接种以预防疾病；before 标出时序。','接种发生在志愿者接触风险之前。'),C('inoculate.s2','培养与观念引入','The biologist inoculated the culture with a harmless bacterium, while the teacher gradually inoculated the class with curiosity about science.','生物学家把无害细菌接入培养物；老师则逐步在班上培养对科学的好奇心。','The biologist inoculated the culture with a harmless bacterium / while the teacher gradually inoculated the class / with curiosity about science.','inoculate 可指向培养物接入微生物，也可比喻逐渐灌输观念；while 对比两种用法。','细菌被加入培养物，好奇心则被比喻为引入学生群体。')],M('The clinic inoculated volunteers against the virus by removing their immunity and increasing their risk of infection.','The clinic inoculated volunteers against the virus by giving them a vaccine to help protect them.','接种旨在引发保护而非降低免疫力。','word-choice'),[Q('inoculate',1,1,'To inoculate a person against a virus is to?','give a vaccine to help protect them','remove all immune protection','teach them to identify a sound','s1 指疫苗接种。'),Q('inoculate',2,2,'A biologist inoculates a culture when they?','introduce microorganisms into it','remove every organism from it','measure it in inches','s2 指向培养物接入微生物。'),Q('inoculate',3,2,'A teacher who inoculates a class with curiosity?','gradually introduces and encourages that attitude','gives the students a vaccine against science','orders students to stop asking questions','inoculate 可比喻逐渐引入观念。'),Q('inoculate',4,1,'Why were volunteers inoculated before field work?','to help protect them from the virus','to make them more likely to catch it','to test their spelling','接种用于预防感染。')]);
P('inoffensive','Inoffensive 由 in- 与 offensive“冒犯的、有害的”构成，形容无害、不太可能使人不快的言行或事物。',C('inoffensive.s1','言行与社交','The speaker chose an inoffensive joke about the rainy weather rather than making a personal comment about a guest.','演讲者选择讲一个关于雨天的无伤大雅的笑话，而没有针对客人作个人评论。','The speaker chose an inoffensive joke about the rainy weather / rather than making / a personal comment about a guest.','inoffensive 修饰 joke，表示不冒犯人；rather than 对比更可能伤人的评论。','天气笑话不针对个人，因此不太可能冒犯来宾。'),M('The joke was inoffensive because it mocked a guest’s disability and upset everyone present.','The joke was offensive because it mocked a guest’s disability and upset everyone present.','嘲笑残障并让在场者难过是冒犯性的。','word-choice'),[Q('inoffensive',1,1,'An inoffensive remark is?','harmless and unlikely to upset people','deliberately cruel and insulting','impossible to understand','inoffensive 表示不冒犯或无害。'),Q('inoffensive',2,1,'Why was the weather joke inoffensive?','it avoided targeting a guest personally','it mocked a guest’s disability','it disclosed private information','不针对个人的轻松笑话较少冒犯人。'),Q('inoffensive',3,1,'Which comment is most likely inoffensive?','“The rain certainly surprised our picnic plans.”','“Your personal condition is ridiculous.”','“I will reveal your private records.”','谈天气不针对个人，较为无害。'),Q('inoffensive',4,1,'Inoffensive is the opposite of?','offensive','informed','inborn','offensive 指冒犯人的。')]);
P('inordinate','Inordinate 源自拉丁语 inordinatus“无序的、过度的”，形容数量或程度大得不合理、过分的。',C('inordinate.s1','时间与程度','The permit process required an inordinate amount of paperwork for a simple replacement sign.','更换一块普通标志竟需要过量的文件手续。','The permit process required an inordinate amount of paperwork / for a simple replacement sign.','inordinate 修饰 amount，表示数量大得不合理；for 对比任务简单。','小事却需要极多文件，程度过分。'),M('The permit required an inordinate amount of paperwork because it used one short form for the entire application.','The permit required a modest amount of paperwork because it used one short form for the entire application.','一份简短表格并不构成过量文件。','word-choice'),[Q('inordinate',1,1,'An inordinate amount is?','unreasonably large or excessive','exactly the expected small amount','impossible to measure because it is zero','inordinate 指过分的、大得不合理的。'),Q('inordinate',2,1,'Why was the paperwork called inordinate?','a simple sign replacement required an excessive amount','the application used only one brief form','the office asked for no documents','简单事项却要求大量材料，显得过分。'),Q('inordinate',3,1,'Which delay is inordinate?','waiting three months for a routine one-day permit','waiting two minutes for a complex review','receiving a reply on the promised date','日常许可等三个月是不合理的。'),Q('inordinate',4,1,'Inordinate is closest to?','excessive','infrequent','inanimate','inordinate 与 excessive 相近。')]);
P('inorganic','Inorganic 由 in- 与 organic 构成，可指非生物来源的物质，也可指不归入有机化合物类别的化合物。',[C('inorganic.s1','生物来源与材料','Glass is inorganic because it is made from mineral materials rather than from living organisms.','玻璃属于无机物，因为它由矿物材料制成，而不是来自生物。','Glass is inorganic / because it is made from mineral materials / rather than from living organisms.','inorganic 描述物质非生物来源；because 解释材料来源。','矿物材料不是生物体组成物。'),C('inorganic.s2','化学分类','The lesson classified sodium chloride as an inorganic compound and compared its structure with that of sugars.','课堂把氯化钠归为无机化合物，并将其结构与糖类作比较。','The lesson classified sodium chloride / as an inorganic compound / and compared its structure with that of sugars.','inorganic 修饰 compound，表示化学上归入无机物；and 连接比较活动。','氯化钠按化学分类属于无机化合物。')],M('The worksheet called glass organic because it comes from living organisms and contains plant cells.','The worksheet called glass inorganic because it comes from mineral materials rather than living organisms.','玻璃来自矿物材料而非生物体。','word-choice'),[Q('inorganic',1,1,'An inorganic material may be?','not derived from living matter','made only from living cells','a person’s natural instinct','s1 指非生物来源。'),Q('inorganic',2,2,'Sodium chloride is classified as?','an inorganic compound','a living organism','a type of insectivore','s2 指无机化合物。'),Q('inorganic',3,1,'Why is glass called inorganic here?','it is made from mineral materials','it is grown from animal tissue','it is a living plant','玻璃由矿物材料制成。'),Q('inorganic',4,2,'Which topic concerns inorganic chemistry?','the properties of salts and minerals','the habits of insect-eating animals','the feeling of social inhibition','无机化学研究盐类和矿物等物质。')]);
P('inquiring','Inquiring 由 inquire 加 -ing 构成，可形容渴望了解的态度，也可形容带有提问意味的目光或语气。',C('inquiring.s1','好奇与提问','The inquiring student stayed after class to ask how the telescope could detect planets beyond our solar system.','这名爱探究的学生下课后留下来询问望远镜如何探测太阳系以外的行星。','The inquiring student stayed after class / to ask how the telescope could detect planets / beyond our solar system.','inquiring 修饰 student，表示求知欲强；to ask 说明学生探究的行为。','学生主动追问原理，体现好奇心。'),M('The student was inquiring because she refused to ask questions and avoided learning anything new.','The student was curious because she asked questions and sought to learn something new.','拒绝提问、回避学习与求知态度相反。','word-choice'),[Q('inquiring',1,1,'An inquiring person is?','eager to learn or ask questions','unwilling to know anything','unaware that a question exists','inquiring 指爱探究的。'),Q('inquiring',2,1,'An inquiring look may seem?','questioning or curious','completely blank and uninterested','angry without any expression','inquiring 也可形容带有询问意味的表情。'),Q('inquiring',3,1,'Why did the student stay after class?','she wanted to learn how the telescope worked','she wanted to avoid every explanation','the telescope was an inordinate distance away','主动了解望远镜体现好奇。'),Q('inquiring',4,1,'Which adjective is closest to inquiring?','curious','insipid','inhospitable','inquiring 接近 curious。')]);
P('insanity','Insanity 是表示精神失常的旧有法律或医学用语，也可在非正式语境中夸张地指极端荒唐；临床判断应使用专业诊断术语。',[C('insanity.s1','法律史与术语','The historical court record used insanity as a legal term, but the modern report described the person’s condition with a specific clinical diagnosis.','历史法庭记录使用了 insanity 这一法律术语，但现代报告以具体临床诊断描述当事人的状况。','The historical court record used insanity as a legal term / but the modern report described the person’s condition / with a specific clinical diagnosis.','insanity 的法律或医学义属于旧有术语；but 对照历史表述与现代诊断。','句子把词放在术语史语境中，避免将其当作现代临床诊断。','register'),C('insanity.s2','夸张与荒唐','Calling a routine two-minute walk “insanity” was an exaggeration, since the route was flat and safe.','把普通的两分钟步行称作“荒唐至极”是一种夸张，因为路线平坦安全。','Calling a routine two-minute walk “insanity” / was an exaggeration / since the route was flat and safe.','insanity 可非正式夸张地指极端荒唐；since 说明夸张之处。','安全短途步行并非真正危险，称其荒唐是夸张。')],M('The historical file used insanity as a precise modern diagnosis accepted in every current clinical system.','The historical file used insanity as an older legal term rather than a precise modern diagnosis.','该词是旧有法律或医学用语，不是通用的现代诊断名。','register'),[Q('insanity',1,1,'In older legal or medical writing, insanity refers to?','a serious disorder of the mind in the terminology of that period','a routine measurement in inches','a new method of farming','s1 是旧有法律或医学用语。'),Q('insanity',2,2,'In informal speech, “That plan is insanity” may mean?','the plan is extremely foolish','the plan is a formal diagnosis','the plan is an inalienable right','s2 可夸张地表示极端荒唐。'),Q('insanity',3,1,'Why should a modern report use a specific clinical term instead?','insanity is an older broad term, not a precise current diagnosis','insanity is the name of a vaccine','modern reports cannot mention mental health','旧词不够精确，需使用适当专业术语。'),Q('insanity',4,2,'Calling a safe two-minute walk insanity is likely?','an exaggeration about something foolish','a verified clinical diagnosis','a description of a legal injunction','日常语境中的荒唐义常是夸张。')]);
P('insatiable','Insatiable 来自拉丁语 insatiabilis，由 in-“不”与 satiare“使满足”相关部分构成，形容欲望总无法满足、永远想要更多。',C('insatiable.s1','欲望与学习','Nora had an insatiable appetite for history and spent every weekend exploring a new archive or museum.','诺拉对历史有着永不满足的热爱，每个周末都会去探索新的档案馆或博物馆。','Nora had an insatiable appetite for history / and spent every weekend / exploring a new archive or museum.','insatiable 修饰 appetite，表示兴趣或欲望总得不到满足；and 补充她持续学习的表现。','她不断寻找新的历史资料，体现求知欲旺盛。'),M('Nora had an insatiable appetite for history because she quickly became satisfied and never wanted to learn more.','Nora had a limited appetite for history because she quickly became satisfied and wanted no more.','很快满足且不再想要与 insatiable 相反。','word-choice'),[Q('insatiable',1,1,'An insatiable desire is one that?','is never fully satisfied','disappears after one small reward','is impossible to notice','insatiable 表示永不满足的。'),Q('insatiable',2,1,'Why was Nora’s appetite for history insatiable?','she continually sought new archives and museums','she stopped learning after one visit','she disliked every historical subject','持续寻求新知识体现永不满足。'),Q('insatiable',3,1,'Which person has an insatiable curiosity?','someone who always wants to discover more','someone who is satisfied by one brief answer forever','someone who refuses to ask questions','不断想了解更多是 insatiable curiosity。'),Q('insatiable',4,1,'The prefix in- in insatiable contributes the meaning?','not','inside','before','in- 在此表示否定。')]);
P('inscription','Inscription 源自拉丁语 inscriptio“写上、刻上”，可指刻在石头、金属或硬币上的文字，也可指写在书或礼物上的题词。',[C('inscription.s1','碑铭与器物','The archaeologists photographed an inscription on the bronze bowl before cleaning the soil from its surface.','考古学家先拍摄了青铜碗上的刻文，然后才清除表面的泥土。','The archaeologists photographed an inscription on the bronze bowl / before cleaning the soil / from its surface.','inscription 指刻在金属等物体上的文字；before 标出保护记录的顺序。','文字刻在青铜碗上，符合铭文义。'),C('inscription.s2','题词与赠礼','A handwritten inscription inside the book thanked the teacher for encouraging the student to write.','书内的手写题词感谢老师鼓励学生写作。','A handwritten inscription inside the book / thanked the teacher / for encouraging the student to write.','inscription 可指写在书或礼物上的简短题词；inside 指题词所在位置。','书内的感谢语是题词。')],M('The archaeologist called the letters carved into the bronze bowl an inscription, although they were printed on a loose paper label.','The archaeologist called the letters engraved directly into the bronze bowl an inscription.','刻在器物表面的文字才是铭文；松散纸标签不是刻文。','word-choice'),[Q('inscription',1,1,'An inscription on a monument is?','text engraved on stone, metal, or a similar surface','a spoken announcement with no written form','a new type of metal ingot','s1 指刻文。'),Q('inscription',2,2,'A handwritten inscription in a gifted book is?','a short dedication or personal message','an engraved law on a stone wall','a method of inoculation','s2 指书或礼物上的题词。'),Q('inscription',3,1,'Where would archaeologists find an inscription?','carved on an ancient coin','spoken during a meeting and never recorded','inside a living animal','铭文常刻在硬币或器物上。'),Q('inscription',4,2,'Why write an inscription inside a book for a teacher?','to add a brief personal dedication','to record a chemical reaction','to describe an animal’s diet','题词用于表达感谢或纪念。')]);
P('insectivorous','Insectivorous 由 insect 与拉丁语 vorare“吞食”相关成分构成，形容主要以昆虫为食的动物或植物。',C('insectivorous.s1','动物与食性','The insectivorous bat left its cave at dusk and hunted moths above the fields.','这只食虫蝙蝠黄昏时离开洞穴，在田地上空捕食飞蛾。','The insectivorous bat left its cave at dusk / and hunted moths / above the fields.','insectivorous 修饰 bat，表示主要吃昆虫；and 连接出洞与捕食行为。','蝙蝠捕食飞蛾，符合食虫动物特征。'),M('The insectivorous bat fed mainly on fruit and never ate insects.','The fruit-eating bat fed mainly on fruit and never ate insects.','主要吃水果、不吃昆虫的蝙蝠不是食虫的。','word-choice'),[Q('insectivorous',1,1,'An insectivorous animal mainly eats?','insects','stones','other animals’ feathers','insectivorous 表示以昆虫为食。'),Q('insectivorous',2,1,'Why is the bat insectivorous?','it hunts moths and other insects','it feeds only on fruit','it is unable to eat','蝙蝠捕食飞蛾，说明其食虫。'),Q('insectivorous',3,1,'Which animal is insectivorous?','a frog that eats beetles','a deer that eats leaves','a fish that eats only algae','主要捕食甲虫的青蛙是食虫动物。'),Q('insectivorous',4,1,'The suffix related to vorare in insectivorous means?','to eat or devour','to live in a house','to make a legal order','vorare 与吞食有关。')]);
P('insecure','Insecure 由 in- 与 secure“安全、牢固的”构成，可指不安全、不稳定，也可形容缺乏自信或关系安全感的人。',[C('insecure.s1','安全与结构','The ladder felt insecure on the wet tiles, so the technician secured its feet before climbing.','梯子放在湿瓷砖上感觉不牢，技师爬上去前先固定了梯脚。','The ladder felt insecure on the wet tiles / so the technician secured its feet / before climbing.','insecure 描述梯子不稳固；so 引出防止滑动的措施。','湿滑地面使梯子不牢，需固定。'),C('insecure.s2','自信与人际','After changing schools, Leo felt insecure about making friends and worried that classmates would reject him.','转学后，利奥对交友缺乏安全感，担心同学会排斥他。','After changing schools / Leo felt insecure about making friends / and worried that classmates would reject him.','insecure 描述缺乏自信或关系安全感；about 引出担忧领域。','担心被排斥体现人际上的不安全感。')],M('The ladder was insecure because it stood firmly on dry ground and could not wobble.','The ladder was secure because it stood firmly on dry ground and could not wobble.','稳固、不摇晃的梯子是 secure。','word-choice'),[Q('insecure',1,1,'An insecure ladder is?','not safe or firmly stable','securely fixed and unable to move','an inbuilt feature','s1 指不稳、不安全。'),Q('insecure',2,2,'Someone insecure about making friends may?','lack confidence and fear rejection','feel completely confident in every relationship','be unable to hear low sound','s2 指缺乏安全感。'),Q('insecure',3,1,'Why did the technician secure the ladder first?','it felt unstable on wet tiles','it was fixed firmly already','the technician wanted to install software','梯子不稳，需要先固定。'),Q('insecure',4,2,'Which feeling suggests insecurity?','worrying that new classmates will reject you','feeling certain that friends support you','enjoying a stable friendship without worry','担心遭到排斥表现出不安全感。')]);
P('insecurity','Insecurity 由 insecure 加 -ity 构成，可指暴露于危险或缺少稳固保障的状态，也可指个人缺乏自信。',[C('insecurity.s1','安全与保障','The bridge’s structural insecurity became clear after inspectors found cracks in two support columns.','检查人员在两根支柱上发现裂缝后，桥梁结构不稳的问题显现出来。','The bridge’s structural insecurity became clear / after inspectors found cracks / in two support columns.','insecurity 指结构不安全或不稳固的状态；after 引出发现问题的时点。','支柱裂缝显示桥梁缺少结构保障。'),C('insecurity.s2','自信与感受','Her insecurity about public speaking made her avoid meetings even when she had useful ideas to share.','她对公开发言缺乏自信，因此即使有有用想法也会避开会议。','Her insecurity about public speaking / made her avoid meetings / even when she had useful ideas to share.','insecurity 描述缺乏自信；about 引出不安所在领域。','因害怕发言而回避会议体现自信不足。')],M('The bridge showed insecurity even though all supports were sound and inspectors found no danger.','The bridge showed security because all supports were sound and inspectors found no danger.','支撑完好且无危险说明桥梁安全。','word-choice'),[Q('insecurity',1,1,'Structural insecurity means?','a state of being unsafe or unstable','a person’s admiration for a musician','the first moment a project begins','s1 指不安全或不稳定状态。'),Q('insecurity',2,2,'Someone’s insecurity about speaking may cause them to?','avoid meetings despite having ideas','speak confidently in every meeting','ignore an inalienable right','s2 指个人缺乏自信。'),Q('insecurity',3,1,'Why were inspectors concerned about the bridge?','cracks showed a lack of structural stability','the columns were new and undamaged','the bridge was an in-depth report','裂缝显示结构可能不安全。'),Q('insecurity',4,2,'Which behavior may come from insecurity?','holding back useful ideas for fear of judgment','sharing an idea with confidence','checking a bridge for cracks','害怕被评价而不发言体现不自信。')]);
P('insensitivity','Insensitivity 由 in-、sensitive 与 -ity 构成，可指对身体刺激反应迟钝，也可指不体会言行对他人感受的影响。',[C('insensitivity.s1','感觉与医疗','The doctor tested the patient’s insensitivity to touch after the injury affected nerves in her hand.','受伤影响手部神经后，医生测试了病人对触摸刺激的迟钝程度。','The doctor tested the patient’s insensitivity to touch / after the injury affected nerves / in her hand.','insensitivity 指对身体刺激反应不足；to touch 指测试的刺激类型。','手部神经受损可能使触觉反应减弱。'),C('insensitivity.s2','沟通与同理心','His insensitivity to the family’s grief showed when he joked about the loss during the memorial.','他在追悼会上拿逝者开玩笑，显出他不顾家属悲痛的感受。','His insensitivity to the family’s grief showed / when he joked about the loss / during the memorial.','insensitivity to 指不觉察言行对他人的影响；when 引出具体表现。','追悼会上开不合时宜的玩笑体现缺乏体察。')],M('His insensitivity to the family’s grief showed when he offered careful support and avoided upsetting jokes.','His sensitivity to the family’s grief showed when he offered careful support and avoided upsetting jokes.','体贴支持并避免伤人玩笑体现敏感体谅，不是麻木。','word-choice'),[Q('insensitivity',1,1,'Physical insensitivity to touch means?','a reduced response to that stimulus','an unusually strong response to every touch','a desire to learn more','s1 指对刺激反应迟钝。'),Q('insensitivity',2,2,'Insensitivity to a family’s grief means?','failing to notice how words affect their feelings','showing careful sympathy','measuring the family’s hearing','s2 指不顾他人感受。'),Q('insensitivity',3,1,'Why did the doctor test touch sensitivity?','the injury may have reduced the hand’s response','the patient wanted a new coat','the injury made the hand inanimate','神经受伤可能影响触觉反应。'),Q('insensitivity',4,2,'Which action shows social insensitivity?','making a joke about someone’s loss at a memorial','offering quiet support to a grieving person','asking privately what help is welcome','不顾场合开逝者玩笑会伤害他人。')]);
P('insidious','Insidious 来自拉丁语 insidiosus、与“设伏、欺骗”相关，形容危害悄悄扩散、起初不易察觉的。',C('insidious.s1','缓慢危害','The insidious leak damaged the wooden floor for months before anyone noticed the stain beneath the rug.','这处隐蔽漏水在地毯下造成污渍，几个月后才有人发现，木地板早已受损。','The insidious leak damaged the wooden floor for months / before anyone noticed / the stain beneath the rug.','insidious 修饰 leak，强调危害缓慢且不易察觉；before 表示发现较晚。','漏水长期暗中造成损害，符合隐伏危害义。'),M('The leak was insidious because everyone noticed it immediately and it caused no damage.','The leak was obvious because everyone noticed it immediately, although it caused no damage.','立即被注意到且没有隐蔽危害，不符合 insidious。','word-choice'),[Q('insidious',1,1,'An insidious problem?','spreads harm slowly and is hard to notice','causes an obvious effect at once','is harmless by definition','insidious 指隐伏地造成危害。'),Q('insidious',2,1,'Why was the leak insidious?','it damaged the floor for months before discovery','it was immediately repaired and caused no harm','it was visible from every room','危害长期未被发现。'),Q('insidious',3,1,'Which threat is insidious?','a contaminant that gradually spreads before symptoms appear','a loud alarm everyone hears at once','a harmless mark noticed immediately','缓慢扩散且不易察觉的污染物具有隐患。'),Q('insidious',4,1,'Insidious is closest in meaning to?','stealthily harmful','inspiring','infrequent','insidious 强调隐蔽危害。')]);
P('insightful','Insightful 由 insight 加 -ful 构成，形容表现出深刻理解的，也可形容善于看透他人隐藏动机的人。',[C('insightful.s1','分析与见解','The reviewer offered an insightful explanation of why the policy failed, connecting its funding rules to the uneven results.','评论者深刻解释了政策失败的原因，把资金规则与不均衡结果联系起来。','The reviewer offered an insightful explanation / of why the policy failed / connecting its funding rules to the uneven results.','insightful 修饰 explanation，表示见解深刻；why 引出解释的主题。','评论者看出了规则和结果间的深层联系。'),C('insightful.s2','人物与洞察','As an insightful counselor, Dana noticed that the student’s repeated jokes were hiding real anxiety.','作为善于洞察的辅导员，达娜注意到学生反复讲笑话其实是在掩饰焦虑。','As an insightful counselor / Dana noticed / that the student’s repeated jokes were hiding real anxiety.','insightful 可形容善于看出他人隐情的人；that 从句呈现她察觉的真相。','辅导员看出了玩笑背后的焦虑。')],M('The reviewer’s explanation was insightful because it repeated the headline without analyzing any cause.','The reviewer’s explanation was shallow because it repeated the headline without analyzing any cause.','只重复标题而无深入分析，不能称为 insight。','word-choice'),[Q('insightful',1,1,'An insightful explanation shows?','clear and deep understanding','no understanding of the subject','a lack of information','s1 指有深刻见解。'),Q('insightful',2,2,'An insightful counselor may?','notice hidden feelings behind a person’s words','ignore every sign of anxiety','install a computer program','s2 指善于洞察他人。'),Q('insightful',3,1,'Why was the reviewer insightful?','they linked funding rules to uneven results','they repeated a headline with no analysis','they avoided reading the policy','发现深层因果关系体现洞察力。'),Q('insightful',4,2,'Dana was insightful because she?','recognized anxiety behind the student’s jokes','assumed the jokes had no meaning','refused to speak with the student','她看出隐藏情绪，体现洞察。')]);
P('insipid','Insipid 来自拉丁语 insipidus，由 in-“无”与 sapidus“有滋味的”相关部分构成，可指食物清淡无味，也可形容作品枯燥无特色。',[C('insipid.s1','味道与食物','The soup tasted insipid until the cook added herbs, salt, and a squeeze of lemon.','这汤尝起来淡而无味，直到厨师加了香草、盐和柠檬汁。','The soup tasted insipid / until the cook added herbs, salt, and a squeeze of lemon.','insipid 描写食物几乎没有味道；until 引出风味改善的时间点。','加调味料前汤味寡淡。'),C('insipid.s2','写作与娱乐','The sequel felt insipid because its characters repeated familiar jokes without any new conflict or surprise.','续集里的角色反复讲熟悉的笑话，也没有新冲突或惊喜，因此显得乏味。','The sequel felt insipid / because its characters repeated familiar jokes / without any new conflict or surprise.','insipid 比喻作品枯燥无特色；because 解释观众觉得乏味的原因。','缺少新内容使续集平淡无味。')],M('The soup was insipid because its bold spices gave it a rich and memorable flavor.','The soup was flavorful because its bold spices gave it a rich and memorable taste.','浓郁鲜明的味道与 insipid 相反。','word-choice'),[Q('insipid',1,1,'Insipid food has?','almost no taste','an intense spicy flavor','an inborn quality','s1 指淡而无味。'),Q('insipid',2,2,'An insipid story is?','dull and without character','full of surprising new ideas','a legal instruction','s2 比喻枯燥乏味。'),Q('insipid',3,1,'Why did the cook add herbs to the insipid soup?','to give it more flavor','to make it less flavorful','to turn it into an infrasound wave','汤太淡，需增加风味。'),Q('insipid',4,2,'Which show might be called insipid?','one that repeats old jokes with no new ideas','one with vivid characters and original twists','one that helps viewers understand a subject','缺乏新意的作品可能显得乏味。')]);
P('insistence','Insistence 由 insist 加 -ence 构成，insist 与拉丁语 insistere“坚持站在某处”相关，指反复坚决要求某事发生或被接受。',C('insistence.s1','要求与坚持','At the tenants’ insistence, the landlord repaired the broken entrance light before the winter evenings began.','在租户们坚决要求下，房东在冬季夜晚到来前修好了坏掉的入口灯。','At the tenants’ insistence / the landlord repaired the broken entrance light / before the winter evenings began.','at someone’s insistence 表示应某人的坚决要求；before 标出维修时限。','租户反复提出要求后，房东采取了行动。'),M('The landlord repaired the light at the tenants’ insistence, although they had never asked for the repair.','The landlord repaired the light at the tenants’ request after they repeatedly asked for it.','没有人提出要求就不能说是应其 insistence。','word-choice'),[Q('insistence',1,1,'Insistence is?','a firm and repeated demand','a casual suggestion mentioned once','a scientific instrument','insistence 指坚决反复的要求。'),Q('insistence',2,1,'The repair happened at the tenants’ insistence. What does that imply?','they firmly demanded the repair','they opposed the repair','they had no opinion about the light','租户坚持要求维修。'),Q('insistence',3,1,'Which action shows insistence?','repeating a clear request until it is addressed','mentioning an idea once and dropping it','ignoring a problem entirely','反复坚决提出要求体现 insistence。'),Q('insistence',4,1,'In “at her insistence,” insistence is closest to?','firm request','accidental click','lack of sleep','该短语表示应她坚决要求。')]);
P('insolent','Insolent 来自拉丁语 insolentem“傲慢、无礼”，形容公开表现出不尊重的粗鲁言行。',C('insolent.s1','礼貌与权威','The clerk objected to the customer’s insolent reply, which mocked her instead of addressing the billing error.','职员反对顾客无礼的回答，因为对方嘲笑她，而没有讨论账单错误。','The clerk objected to the customer’s insolent reply / which mocked her / instead of addressing the billing error.','insolent 修饰 reply，表示公开无礼；which 从句说明冒犯方式。','嘲笑职员而不谈问题体现傲慢无礼。'),M('The customer gave an insolent reply by thanking the clerk respectfully and discussing the bill calmly.','The customer gave a respectful reply by thanking the clerk and discussing the bill calmly.','礼貌感谢并平静沟通与 insolent 相反。','word-choice'),[Q('insolent',1,1,'An insolent reply is?','openly rude and disrespectful','carefully polite and grateful','a legal order to stop an action','insolent 表示傲慢无礼。'),Q('insolent',2,1,'Why was the customer’s reply insolent?','it mocked the clerk instead of discussing the bill','it thanked the clerk and stayed calm','it corrected the billing error politely','嘲笑职员体现公开不尊重。'),Q('insolent',3,1,'Which behavior is insolent?','speaking contemptuously to a person in charge','listening and asking a respectful question','apologizing for a mistake','轻蔑地对待负责人属于无礼。'),Q('insolent',4,1,'Insolent is closest in meaning to?','disrespectful','inborn','infrequent','insolent 与 disrespectful 相近。')]);
P('insoluble','Insoluble 由 in- 与 soluble“可溶解的”构成，可指不能溶于液体，也可比喻无法解决或解释的难题。',[C('insoluble.s1','化学与溶解','Sand is insoluble in water, so the grains settle at the bottom instead of disappearing.','沙子不溶于水，因此颗粒会沉到容器底部，而不是消失。','Sand is insoluble in water / so the grains settle at the bottom / instead of disappearing.','insoluble in 表示不溶于某液体；so 引出颗粒沉淀的结果。','沙粒没有溶解，仍沉在水底。'),C('insoluble.s2','难题与解决','The missing ledger created an insoluble mystery until a copy was found in the archive.','失踪的账簿一度造成无法解开的谜团，直到档案馆里找到一份副本。','The missing ledger created an insoluble mystery / until a copy was found / in the archive.','insoluble 可比喻无法解决或解释；until 表示谜团何时得到破解。','账簿副本找到前，谜团无法解释。')],M('The sand was insoluble in water because it dissolved completely and vanished from the glass.','The sand was soluble in water because it dissolved completely and vanished from the glass.','完全溶解说明可溶，而不是 insoluble。','confusable'),[Q('insoluble',1,1,'An insoluble powder?','cannot dissolve in a liquid','dissolves instantly in every liquid','is impossible to measure in inches','s1 指不溶解。'),Q('insoluble',2,2,'An insoluble mystery is?','impossible or very difficult to solve','already fully explained','a new installation ceremony','s2 比喻无法解决。'),Q('insoluble',3,1,'Why did sand settle at the bottom of water?','it was insoluble and remained as grains','it dissolved completely','it became an infrasound wave','沙粒不溶于水，因而沉淀。'),Q('insoluble',4,2,'A case remains insoluble until evidence appears. What does that mean?','it cannot yet be solved','it has already been solved','it is a substance in a liquid','此处表示谜案尚无法解决。')]);
P('insomnia','Insomnia 来自拉丁语 insomnia，由 in-“不”与 somnus“睡眠”组成，指持续难以入睡或维持睡眠的状况。',C('insomnia.s1','睡眠与健康','After several weeks of insomnia, Elena spoke with a clinician about routines that might help her sleep through the night.','连续失眠数周后，埃琳娜向临床人员咨询哪些作息习惯可能帮助她整夜安睡。','After several weeks of insomnia / Elena spoke with a clinician / about routines that might help her sleep through the night.','insomnia 指持续入睡困难或睡眠维持困难；after several weeks 强调问题持续。','数周难以睡整夜符合失眠的描述。'),M('The patient’s insomnia meant that she fell asleep immediately every night and never woke up.','The patient’s restful sleep meant that she fell asleep immediately every night and never woke up.','轻松入睡且整夜不醒与 insomnia 相反。','word-choice'),[Q('insomnia',1,1,'Insomnia is persistent difficulty?','falling asleep or staying asleep','hearing low-frequency sound','installing a computer program','insomnia 指持续睡眠困难。'),Q('insomnia',2,1,'Why did Elena consult a clinician?','she had struggled to sleep for several weeks','she slept soundly every night','she wanted to study an ingot','持续睡眠问题促使她咨询专业人士。'),Q('insomnia',3,1,'Which pattern may indicate insomnia?','regularly waking and being unable to return to sleep','sleeping through the night with ease','choosing to stay awake for one special event','反复醒来难以再入睡符合睡眠困难。'),Q('insomnia',4,1,'The prefix in- in insomnia contributes the sense?','not','inside','between','该词由否定前缀和睡眠相关词根构成。')]);
P('inspiration','Inspiration 来自拉丁语 inspirare“吹入、灌注”，可指突然出现的巧妙想法，也可指鼓舞他人进步的人或事物。',[C('inspiration.s1','创意与灵感','A sketch of a folded leaf gave Arun the inspiration for a compact emergency shelter.','一片折叠树叶的草图给了阿伦灵感，使他设计出紧凑型应急帐篷。','A sketch of a folded leaf / gave Arun the inspiration / for a compact emergency shelter.','inspiration 指解决问题的突然好点子；for 引出灵感产生的设计。','树叶结构引发了帐篷设计想法。'),C('inspiration.s2','榜样与鼓励','Her former teacher remained an inspiration to the young scientists, encouraging them to pursue difficult questions.','她的启蒙老师一直是年轻科学家的榜样，鼓励他们探究困难问题。','Her former teacher remained an inspiration to the young scientists / encouraging them / to pursue difficult questions.','inspiration 可指鼓舞他人的人；to 标明受鼓舞的人。','老师持续鼓励学生努力探索。')],M('The folded leaf was an inspiration for the shelter because it gave Arun no idea and discouraged him from designing anything.','The folded leaf provided inspiration for the shelter by giving Arun a useful design idea.','启发设计灵感与完全没有想法、打击创作相反。','word-choice'),[Q('inspiration',1,1,'An inspiration for a design is?','a sudden clever idea that helps solve a problem','a rule that prevents all new ideas','a metal block for later working','s1 指解决问题的灵感。'),Q('inspiration',2,2,'A teacher can be an inspiration to students by?','encouraging them to do well','discouraging them from learning','measuring their classroom in inches','s2 指鼓舞人心的人。'),Q('inspiration',3,1,'Why did Arun design the shelter after seeing the leaf?','its shape gave him a new idea','he had no idea and abandoned the project','the leaf was an installed machine','叶片结构启发了帐篷设计。'),Q('inspiration',4,2,'Which person might be an inspiration to young scientists?','a mentor who encourages careful discovery','a person who mocks every question','a stranger who hides all information','鼓励研究的人可以成为榜样。')]);
P('inspiring','Inspiring 由 inspire 加 -ing 构成，形容使人充满热情、希望或行动意愿的。',C('inspiring.s1','故事与行动','The inspiring account of the volunteers rebuilding the playground motivated other neighborhoods to organize cleanups.','志愿者重建操场的鼓舞人心故事促使其他社区也组织清理活动。','The inspiring account of the volunteers rebuilding the playground / motivated other neighborhoods / to organize cleanups.','inspiring 修饰 account，表示能激励他人；motivated 说明其影响。','读者受到故事鼓舞并采取行动。'),M('The speech was inspiring because it left listeners hopeless and unwilling to do anything.','The speech was discouraging because it left listeners hopeless and unwilling to act.','让听众失去希望与鼓舞人心相反。','word-choice'),[Q('inspiring',1,1,'An inspiring story makes people feel?','hopeful or eager to act','bored and unwilling to try','unable to understand any words','inspiring 指鼓舞人心的。'),Q('inspiring',2,1,'Why was the volunteer account inspiring?','it motivated other neighborhoods to help','it persuaded everyone to abandon the playground','it contained no example of action','故事带动他人参与行动。'),Q('inspiring',3,1,'Which speaker sounds inspiring?','one who gives listeners hope and a reason to contribute','one who tells listeners that nothing can improve','one who refuses to explain the goal','激发希望并鼓励贡献属于鼓舞。'),Q('inspiring',4,1,'Inspiring is related to which noun?','inspiration','insecurity','insomnia','inspiring 与 inspiration 同源。')]);
P('instability','Instability 由 in- 与 stability 构成，指结构、系统或局势缺乏稳固与平衡的状态。',C('instability.s1','结构与风险','Inspectors closed the old balcony after discovering instability in its support beams.','检查人员发现支撑梁不稳后关闭了旧阳台。','Inspectors closed the old balcony / after discovering instability / in its support beams.','instability 指结构缺少稳固；after 引出采取关闭措施的原因。','支撑梁不稳定会造成安全风险。'),M('The balcony’s instability was ruled out because its support beams were sound and steady.','The balcony’s stability was confirmed because its support beams were sound and steady.','支撑梁完好稳固，说明阳台稳定。','word-choice'),[Q('instability',1,1,'Instability in a structure means?','lack of steadiness or firmness','a permanent guarantee of safety','a detailed source of information','instability 指不稳定。'),Q('instability',2,1,'Why was the balcony closed?','its support beams were unstable','its supports had been verified as sound','it had an inbuilt bench','结构不稳导致关闭。'),Q('instability',3,1,'Which situation shows political instability?','frequent upheaval that makes government uncertain','a settled system with predictable transitions','a single accurate measurement','频繁动荡使政治体系不稳。'),Q('instability',4,1,'Instability is the opposite of?','stability','insistence','inhumanity','stability 意为稳定。')]);
P('install','Install 经古法语与拉丁语相关词演变，可指把软件装入计算机、把设备固定就位，或以仪式使某人正式就任。',[C('install.s1','软件与计算机','The librarian installed the catalog update on every public computer before the new semester began.','新学期开始前，图书管理员在每台公共电脑上安装了目录更新程序。','The librarian installed the catalog update / on every public computer / before the new semester began.','install software 表示把程序装入电脑；before 标出安装期限。','更新程序被放到电脑中以供使用。'),C('install.s2','设备与固定','Workers installed a handrail along the ramp to make the entrance safer for wheelchair users.','工人沿坡道安装了扶手，让轮椅使用者进出时更安全。','Workers installed a handrail along the ramp / to make the entrance safer / for wheelchair users.','install 表示把设备固定到适当位置；to 引出安装目的。','扶手被固定在坡道边。'),C('install.s3','任职与仪式','The board installed the new director during a short ceremony attended by staff and community partners.','董事会在一场有员工和社区伙伴参加的简短仪式上正式任命了新主任。','The board installed the new director / during a short ceremony / attended by staff and community partners.','install someone 表示正式使其就职；during 引出任命仪式。','新主任通过仪式正式就任。')],M('The technician installed the software by deleting it from the computer before anyone could use it.','The technician uninstalled the software by deleting it from the computer.','删除程序是卸载，不是安装。','confusable'),[Q('install',1,1,'To install software is to?','put a program onto a computer for use','remove a program from a computer','appoint a person to office','s1 指安装软件。'),Q('install',2,2,'Workers installed a handrail when they?','fixed it in position along the ramp','removed it from the entrance','used it to store software','s2 指安放、固定设备。'),Q('install',3,3,'The board installed a director during a ceremony. It?','formally placed the person in office','removed the person from office','installed a computer program','s3 指正式使某人就职。'),Q('install',4,1,'Which action installs an app?','adding it to a device so it can be used','deleting it from the device','writing its name on paper only','安装应用是将程序添加到设备。')]);
P('installation','Installation 由 install 加 -ation 构成，可指设备安装过程、固定在某处的大型系统或装置，也可指正式就职仪式。',[C('installation.s1','施工与安装过程','The installation of the new water filter took two hours, including a leak check and a test run.','新净水器的安装花了两小时，包括检漏和试运行。','The installation of the new water filter took two hours / including a leak check / and a test run.','installation 指安装设备的行为或过程；including 列出流程环节。','安装过程包含固定滤水器并检查运行。'),C('installation.s2','大型装置','The heating installation in the old school occupies a separate utility room beneath the auditorium.','旧学校的供暖设备系统占据礼堂下方的一间独立机房。','The heating installation in the old school / occupies a separate utility room / beneath the auditorium.','installation 可指固定在某处的大型设备系统；in 引出系统所在建筑。','整套供暖装置安装在固定机房。'),C('installation.s3','就职仪式','Guests attended the installation of the new university president in the central hall.','来宾在中央大厅参加了新任大学校长的就职典礼。','Guests attended the installation of the new university president / in the central hall.','installation 可指正式使某人就任的仪式；of 后说明就职者。','来宾参加正式就职典礼。')],M('The installation of the filter meant the old unit was removed and no replacement equipment was put in place.','The removal of the filter meant the old unit was taken out without installing replacement equipment.','没有放入新设备不是安装过程。','word-choice'),[Q('installation',1,1,'The installation of equipment is?','the act of putting it into position for use','the act of deleting software','a person’s lack of confidence','s1 指安装过程。'),Q('installation',2,2,'A heating installation is?','a fixed system or set of equipment','a one-time greeting at a ceremony','a small unit of length','s2 指固定设备系统。'),Q('installation',3,3,'The installation of a university president is?','a ceremony formally placing the person in office','the removal of all heating equipment','a software update','s3 指就职典礼。'),Q('installation',4,1,'Why did workers inspect the filter during installation?','to ensure the equipment was fitted and worked properly','to remove the whole system permanently','to elect a university president','安装时需要确认设备装好并运行正常。')]);
P('installment','Installment 是 installment/instalment 的常见拼写之一，由 install 的“分批安置”概念发展而来，可指分期付款中的一期，也可指连载作品的一期。',[C('installment.s1','付款与账单','The buyer paid the final installment on the bicycle, completing the agreed twelve-month payment plan.','买家付清了自行车的最后一期款项，完成约定的十二个月分期计划。','The buyer paid the final installment on the bicycle / completing the agreed / twelve-month payment plan.','installment 指一系列定期付款中的一期；final 表明这是最后一笔。','付款计划分成多期逐次偿还。'),C('installment.s2','连载与出版','The magazine’s latest installment of the mystery ends just as the detective finds a hidden key.','这本杂志最新一期的连载悬疑故事在侦探发现一把暗藏钥匙时结束。','The magazine’s latest installment of the mystery / ends just as the detective finds / a hidden key.','installment 可指分部分刊出的故事中的一期；latest 表示系列当前一部分。','故事按期连载，钥匙发现处形成这一期的结尾。')],M('The buyer paid one installment, meaning she paid the entire twelve-month amount at once.','The buyer paid one installment, meaning she paid one scheduled portion of the twelve-month amount.','一期付款只是总额的一部分，不是一次付清。','meaning'),[Q('installment',1,1,'A payment installment is?','one of a series of regular payments','the entire debt paid once','a legal order to stop an action','s1 指分期中的一期。'),Q('installment',2,2,'A magazine installment of a mystery is?','one part of a story released in sections','the final payment on a bicycle','a fixed heating system','s2 指连载故事的一期。'),Q('installment',3,1,'Why did the buyer pay the final installment?','to complete the scheduled payment plan','to begin an unrelated story','to install the bicycle software','最后一期款项完成分期计划。'),Q('installment',4,2,'If a mystery is published in installments, readers receive it?','in separate parts over time','as one unpublished block of metal','only after the story is forgotten','连载作品分期刊出。')]);
P('instantaneous','Instantaneous 由 instant 加 -aneous 构成，指在极短的一瞬间发生的，也可强调没有等待、立刻完成的。',[C('instantaneous.s1','时间与变化','The camera captured the instantaneous flash produced when the circuit briefly connected.','电路短暂接通时产生闪光，摄像机捕捉到了这一瞬间的亮光。','The camera captured the instantaneous flash / produced when the circuit briefly connected.','instantaneous 修饰 flash，强调变化在极短时间内发生；when 引出触发时刻。','闪光几乎在一瞬间出现。'),C('instantaneous.s2','响应与服务','The new alert system provides instantaneous confirmation as soon as a message reaches the server.','新警报系统在消息抵达服务器时立即给出确认。','The new alert system provides instantaneous confirmation / as soon as a message reaches the server.','instantaneous 修饰 confirmation，强调无需等待；as soon as 表示触发后立即发生。','服务器收到消息后马上确认。')],M('The system’s instantaneous response arrived several days after the message was received.','The system’s delayed response arrived several days after the message was received.','等待数日才到达的响应不是瞬间的。','word-choice'),[Q('instantaneous',1,1,'An instantaneous flash happens?','in one very short moment','after a long delay','only in the innermost room','s1 指瞬间发生。'),Q('instantaneous',2,2,'Instantaneous confirmation is given?','with no waiting after the trigger','several weeks after a request','only when a user cancels','s2 指即时、不等待。'),Q('instantaneous',3,1,'Which event is instantaneous?','a brief flash when a circuit connects','a letter delivered after a month','a slow repair taking a year','瞬间出现的闪光符合该词。'),Q('instantaneous',4,2,'Why did the alert system seem instantaneous?','it confirmed the message as soon as it arrived','it waited until the next month','it never received the message','即时确认无需等待。')]);
P('instantaneously','Instantaneously 由 instantaneous 加 -ly 构成，表示在几乎不可察觉的时间间隔内、立刻发生。',C('instantaneously.s1','速度与反应','When the sensor detected smoke, the sprinkler valve opened instantaneously and water began to flow.','传感器一检测到烟雾，洒水阀就瞬间打开并开始出水。','When the sensor detected smoke / the sprinkler valve opened instantaneously / and water began to flow.','instantaneously 修饰 opened，表示几乎没有可察觉的延迟；when 引出触发事件。','探测到烟雾后阀门立即打开。'),M('The valve opened instantaneously several hours after the sensor detected smoke.','The valve opened several hours after the sensor detected smoke.','延迟数小时不是瞬间动作。','word-choice'),[Q('instantaneously',1,1,'If a valve opens instantaneously, it opens?','at once with no perceptible interval','after several hours','only after the building is rebuilt','instantaneously 表示瞬间地。'),Q('instantaneously',2,1,'What happened after the smoke sensor triggered?','the valve opened immediately','the valve waited several hours','the sensor became a payment installment','传感器触发后阀门立刻开启。'),Q('instantaneously',3,1,'Which action occurs instantaneously?','a light flashes at the exact signal','a package arrives after three weeks','a wall is built over several months','信号到来时的闪光几乎没有延迟。'),Q('instantaneously',4,1,'Instantaneously is the adverb form of?','instantaneous','insoluble','inquisitive','instantaneously 由 instantaneous 派生。')]);
P('instantly','Instantly 由 instant 加 -ly 构成，表示立即、马上发生或完成。',C('instantly.s1','即时反应','The emergency operator answered instantly when the alarm line rang during the night.','夜间警报线路响起时，应急接线员立即接听。','The emergency operator answered instantly / when the alarm line rang / during the night.','instantly 修饰 answered，表示立即采取行动；when 引出触发时刻。','线路响起后接线员马上接听。'),M('The operator answered instantly by waiting until the next morning to pick up the call.','The operator answered the call the next morning, rather than instantly.','等到第二天早上不是立即回应。','word-choice'),[Q('instantly',1,1,'To respond instantly is to respond?','immediately','after a long delay','only in exchange for payment','instantly 表示马上。'),Q('instantly',2,1,'When did the operator answer?','as soon as the alarm line rang','the following week','before the line was installed','接线员在线路响后立即接听。'),Q('instantly',3,1,'Which sentence uses instantly correctly?','The screen went dark instantly after power was cut.','The screen went instantly darkness to the table.','The screen was instantly of a computer.','副词修饰 went dark，表示立即变黑。'),Q('instantly',4,1,'Instantly is closest in meaning to?','at once','in the interim','in part','instantly 与 at once 意思相近。')]);
P('instigate','Instigate 来自拉丁语 instigare“催促、煽动”，指发起某事，尤其是引发困难或暴力事件。',C('instigate.s1','冲突与煽动','Investigators found that a false message instigated the fight by urging rival groups to meet at the same narrow bridge.','调查人员发现，一条虚假消息煽动了这场斗殴：它怂恿敌对团体在同一座狭窄桥上碰面。','Investigators found that a false message instigated the fight / by urging rival groups / to meet at the same narrow bridge.','instigate 表示挑起或引发冲突；by 引出煽动方式。','消息促使敌对团体冲突，说明它引发争斗。'),M('The mediator instigated the conflict by calming both groups and persuading them to leave peacefully.','The mediator prevented the conflict by calming both groups and persuading them to leave peacefully.','平息冲突与煽动冲突相反。','word-choice'),[Q('instigate',1,1,'To instigate a fight is to?','cause or provoke it to begin','calm it after it has ended','measure the distance between groups','instigate 指引发或挑起。'),Q('instigate',2,1,'Why did investigators say the message instigated the fight?','it urged rival groups to meet in a tense setting','it persuaded both groups to stay apart','it documented the fight afterward','消息促使双方碰面并引发冲突。'),Q('instigate',3,1,'Which action might instigate a difficult event?','deliberately provoking two groups to clash','helping them agree on a peaceful plan','recording the event after it ends','故意挑动冲突可能引发困难事件。'),Q('instigate',4,1,'Instigate is closest in meaning to?','provoke','inspire','install','instigate 强调挑起、煽动。')]);
P('instil','Instil 是英国英语中常用拼法，来自拉丁语 instillare“滴入”，引申为逐渐使某人形成某种态度或习惯。',C('instil.s1','教育与习惯','The coach tried to instil patience in the young players by praising careful practice rather than quick wins.','教练通过表扬认真练习而非只看速胜，努力让年轻队员逐渐养成耐心。','The coach tried to instil patience in the young players / by praising careful practice / rather than quick wins.','instil an attitude in someone 表示逐渐培养某种态度；by 引出培养方式。','反复鼓励耐心练习意在使队员逐步形成耐心。','英式拼法；美式常写 instill。'),M('The coach instilled patience by encouraging players to act impulsively and abandon careful practice.','The coach instilled impatience by encouraging players to act impulsively and abandon careful practice.','鼓励冲动和放弃练习不会培养耐心。','word-choice'),[Q('instil',1,1,'To instil an attitude is to?','help someone acquire it gradually','remove it instantly','measure it in inches','instil 表示逐渐灌输或培养。'),Q('instil',2,1,'How did the coach try to instil patience?','by praising careful practice over quick wins','by rewarding only impulsive play','by ending every practice immediately','反复肯定耐心练习可培养耐心。'),Q('instil',3,1,'Which use of instil is correct?','Teachers can instil curiosity through thoughtful questions.','Teachers can instil the classroom into a chair.','Teachers instil because the answer is six inches.','instil 可接 curiosity 等态度名词。'),Q('instil',4,1,'Instil is commonly the British spelling of the verb also written?','instill','insulate','install','instil 与美式 instill 是拼写变体。')]);
P('instill','Instill 是美式英语中常用拼法，来自拉丁语 instillare“滴入”，引申为通过持续教导逐渐植入态度或原则。',C('instill.s1','教育与价值观','Parents can instill respect for other people by modeling patient listening at home.','父母可以通过在家示范耐心倾听，逐渐让孩子学会尊重他人。','Parents can instill respect for other people / by modeling patient listening / at home.','instill 表示逐渐培养态度；by 引出家长的示范方式。','持续示范耐心倾听有助于培养尊重。','美式常用双写 l；英式常写 instil，两者均为正确拼法。'),M('The family instilled respect by teaching the child to mock and interrupt everyone.','The family instilled disrespect by teaching the child to mock and interrupt everyone.','嘲笑和打断他人培养的是不尊重。','word-choice'),[Q('instill',1,1,'To instill a value is to?','implant it gradually through teaching or example','remove it from someone in one moment','appoint someone to office','instill 表示逐渐灌输。'),Q('instill',2,1,'How can parents instill respect?','model patient listening and considerate behavior','mock others and interrupt them','avoid speaking to children','示范尊重行为可逐渐培养价值观。'),Q('instill',3,1,'Which phrase is natural?','instill confidence in a new learner','instill the learner into a desk','instill a ruler to measure a wall','常用搭配是 instill confidence in someone。'),Q('instill',4,1,'Instill and instil are?','American and British spellings of the same verb','two unrelated words with opposite meanings','a noun and an adjective','两者是同一动词的拼写变体。')]);
P('instillment','Instillment 由 instill 加 -ment 构成，指通过持续教导逐渐灌输观念或价值，也可指液体逐滴引入。',[C('instillment.s1','教育与滴注','The instillment of confidence took time, as mentors encouraged each trainee to practice one skill at a time.','信心的逐步建立需要时间，导师鼓励每位学员一次专练一种技能。','The instillment of confidence took time / as mentors encouraged each trainee / to practice one skill at a time.','instillment 指态度或信念的逐渐灌输；as 引出其发生方式。','导师逐渐培养学员的信心。'),C('instillment.s1','医疗与液体','The nurse controlled the instillment of saline drops so the patient received the solution at the prescribed rate.','护士控制生理盐水滴注过程，确保病人按规定速度接受液体。','The nurse controlled the instillment of saline drops / so the patient received the solution / at the prescribed rate.','instillment 也可指液体逐滴引入；so 引出控制速度的目的。','盐水逐滴进入，符合液体滴注义。')],M('The instillment of confidence happened instantly without any teaching, practice, or encouragement.','The gradual instillment of confidence came through teaching, practice, and encouragement.','没有渐进过程的突然变化不符合该词的逐步灌输义。','meaning'),[Q('instillment',1,1,'Instillment can mean?','gradually introducing ideas or values','removing all ideas from a group','a public ceremony for an officeholder','该名词指逐渐灌输。'),Q('instillment',2,1,'The instillment of saline drops is?','introducing the liquid drop by drop','pouring the entire container at once','measuring a patient’s height','该词也可表示液体滴注。'),Q('instillment',3,1,'Why did confidence require instillment?','mentors built it gradually through practice','it appeared fully formed in one second','the trainees refused all instruction','信心通过练习逐渐形成。'),Q('instillment',4,1,'Instillment is formed from instill plus?','a noun-forming suffix','a prefix meaning under','a suffix that marks a plural verb','-ment 构成名词。')]);
P('instilment','Instilment 是 instil 的名词加 -ment，指逐渐培养某种态度，也可指液体一滴一滴地加入。',C('instilment.s1','态度与指导','The instilment of confidence in new volunteers began with small tasks and regular feedback.','对新志愿者信心的逐步培养，从小任务和定期反馈开始。','The instilment of confidence in new volunteers / began with small tasks / and regular feedback.','instilment 指逐渐培养态度；began with 表明起步方式。','小任务和反馈逐步建立志愿者的信心。'),M('The instilment of confidence happened all at once and involved no gradual teaching or practice.','The instilment of confidence occurred gradually through teaching and practice.','突然发生、没有渐进培养过程与该词义不符。','meaning'),[Q('instilment',1,1,'Instilment means?','the gradual teaching of an attitude or addition of liquid drop by drop','the sudden removal of an attitude','the completion of an installment payment','instilment 指逐渐灌输或滴加。'),Q('instilment',2,1,'What helped with the instilment of confidence?','small tasks and regular feedback','a single unexplained command','removing all chances to practice','连续反馈和练习逐步培养信心。'),Q('instilment',3,1,'A nurse’s instilment of liquid would happen?','one drop at a time','all at once in a large spill','only after the medicine is removed','该名词可指逐滴加液体。'),Q('instilment',4,1,'Instilment is the noun form related to?','instil','instantly','insufferable','instilment 对应动词 instil。')]);
P('instinctively','Instinctively 由 instinct 加 -ive 与 -ly 构成，表示依本能自动反应，而非经过有意思考。',C('instinctively.s1','本能反应','When the glass slipped, he instinctively reached out to catch it before it struck the floor.','杯子滑落时，他本能地伸手去接，免得它摔在地上。','When the glass slipped / he instinctively reached out to catch it / before it struck the floor.','instinctively 修饰 reached，表示动作自动发生；before 引出动作目的。','伸手接杯子是迅速的本能反应。'),M('She instinctively planned every step for weeks before making the deliberate response.','She deliberately planned every step for weeks before making the response.','经过数周有意计划的行动不是 instinctively 的自动反应。','word-choice'),[Q('instinctively',1,1,'To react instinctively is to react?','automatically, without deliberate thought','after weeks of careful planning','only when given a written order','instinctively 表示本能地。'),Q('instinctively',2,1,'Why did he reach for the slipping glass instinctively?','the response happened automatically and quickly','he had planned the exact moment for weeks','he wanted the glass to break','伸手动作自动且迅速。'),Q('instinctively',3,1,'Which response is instinctive?','pulling a hand back from sudden heat','writing a report after careful research','choosing a new job after months of comparison','突然避开烫热是自动反应。'),Q('instinctively',4,1,'Instinctively is related to the noun?','instinct','institution','insistence','instinctively 由 instinct 派生。')]);
P('instinctual','Instinctual 由 instinct 加形容词后缀 -ual 构成，形容源自本能而非教导或推理的行为。',C('instinctual.s1','本能与行为','The infant’s instinctual grip tightened around the caregiver’s finger without anyone teaching the motion.','婴儿没有受过动作指导，就本能地紧紧抓住照护者的手指。','The infant’s instinctual grip tightened / around the caregiver’s finger / without anyone teaching the motion.','instinctual 修饰 grip，表示本能产生；without 强调并非通过教学学会。','婴儿无需指导便出现抓握反应。'),M('The grip was instinctual because the infant learned it through years of formal lessons.','The grip was learned through practice because the infant acquired it through formal lessons.','通过多年课程习得的动作不是天生本能。','word-choice'),[Q('instinctual',1,1,'An instinctual behavior comes from?','instinct rather than teaching or reasoning','a legal injunction','a long payment plan','instinctual 表示本能的。'),Q('instinctual',2,1,'Why was the infant’s grip instinctual?','no one had taught the response','the child practiced it for years','it was installed as a device','婴儿未受指导便抓握，体现本能。'),Q('instinctual',3,1,'Which is most likely instinctual?','an automatic response present without training','a complex routine mastered after lessons','a carefully reasoned legal decision','无需训练的自动反应符合该词。'),Q('instinctual',4,1,'Instinctual is related to which noun?','instinct','installment','insulation','instinctual 与 instinct 同根。')]);
P('institutional','Institutional 由 institution 加 -al 构成，形容与医院、银行、法律等机构或其制度相关的。',C('institutional.s1','机构与规则','The report compared institutional policies at several hospitals, focusing on how each handled patient records.','报告比较了几家医院的机构政策，重点考察它们如何处理患者记录。','The report compared institutional policies / at several hospitals / focusing on how each handled patient records.','institutional 修饰 policies，表示机构层面的制度；at 指政策所属机构。','报告比较不同医院的规章制度。'),M('The review examined institutional rules that had no connection to any organization or formal system.','The review examined personal habits rather than institutional rules.','个人习惯与机构制度不是同一层面。','word-choice'),[Q('institutional',1,1,'Institutional rules are connected with?','organizations or formal institutions','a person’s reflex alone','a unit of length','institutional 指机构或制度相关的。'),Q('institutional',2,1,'Why compare hospital institutional policies?','to examine how organizations handle patient records','to measure how far the hospitals are apart','to find an insectivorous animal','医院政策属于机构制度。'),Q('institutional',3,1,'Which is institutional?','a bank’s formal lending policy','one person’s private preference','a sudden instinctive reaction','银行的正式政策属于机构层面。'),Q('institutional',4,1,'Institutional is derived from the noun?','institution','instinct','installation','institutional 由 institution 派生。')]);
P('institutionalize','Institutionalize 由 institution 加 -alize 构成，可指使惯例成为机构固定制度，也可指长期将某人送入医院或类似收容机构。',[C('institutionalize.s1','制度与惯例','The museum institutionalized its annual accessibility review by adding it to the official budget and staff calendar.','博物馆把年度无障碍评估纳入正式预算和员工日历，使其成为固定制度。','The museum institutionalized its annual accessibility review / by adding it to the official budget / and staff calendar.','institutionalize 指使惯例固定为机构制度；by 引出制度化做法。','预算和日程安排把年度评估固定下来。'),C('institutionalize.s2','长期照护与安置','In the historical account, the family institutionalized their relative in a long-term care facility when community support was unavailable.','历史记述中，由于缺少社区支持，家人把亲属长期安置在照护机构。','In the historical account / the family institutionalized their relative / in a long-term care facility / when community support was unavailable.','institutionalize 可指长期安置于医院或类似机构；in 引出机构地点。','该词在此描述长期机构安置，语气可能显得过时或负面。','register')],M('The museum institutionalized its review by keeping it informal and omitting it from every official policy and schedule.','The museum kept the review informal and outside its official policies and schedules.','不纳入正式流程说明没有制度化。','meaning'),[Q('institutionalize',1,1,'To institutionalize a practice is to?','make it a fixed part of an organization','remove it from every policy','install a computer program','s1 指使惯例制度化。'),Q('institutionalize',2,2,'In the historical care sense, to institutionalize someone is to?','place them in a hospital or similar institution for a long time','appoint them to an office ceremony','teach them an instinctive response','s2 指长期机构安置。'),Q('institutionalize',3,1,'How did the museum institutionalize the review?','it added the review to official budgets and schedules','it stopped conducting the review','it left the review to informal conversation only','把评估写入预算和日程使之固定。'),Q('institutionalize',4,2,'Which context uses the long-term placement sense?','a historical account of someone entering residential care','a museum adding a policy to its annual rules','a bank writing a new procedure','长期入住照护机构符合该义。')]);
P('instructive','Instructive 由 instruct 加 -ive 构成，形容能提供信息、让人从中学习或得到教益的内容。',C('instructive.s1','经验与学习','The first repair attempt was instructive because it showed the apprentices which seal had been fitted backward.','第一次维修尝试很有启发，因为它让学徒们看清哪一个密封圈装反了。','The first repair attempt was instructive / because it showed the apprentices / which seal had been fitted backward.','instructive 修饰 attempt，表示能提供学习经验；because 引出收获。','尝试暴露了具体装配错误，帮助学徒学习。'),M('The demonstration was instructive because it hid every step and gave students no information to learn from.','The demonstration was uninformative because it hid every step and gave students nothing to learn from.','没有信息可学的演示不能称为 instructive。','word-choice'),[Q('instructive',1,1,'An instructive example?','provides information from which people can learn','prevents anyone from understanding the topic','is only an inordinate expense','instructive 指有启发、有教益。'),Q('instructive',2,1,'Why was the repair attempt instructive?','it revealed which seal had been fitted backward','it concealed all errors from the apprentices','it gave no one useful information','错误提供了学习机会。'),Q('instructive',3,1,'Which experience is instructive?','a demonstration that explains why a method failed','a hidden process with no explanation','an unrelated rumor','解释失败原因的示范能让人学习。'),Q('instructive',4,1,'Instructive is related to which verb?','instruct','insist','insure','instructive 与 instruct 同源。')]);
P('instrumental','Instrumental 由 instrument 加 -al 构成，可表示对促成结果起关键作用，也可指乐器或器乐相关的。',[C('instrumental.s1','作用与结果','Community volunteers were instrumental in reopening the library after they organized repairs and a donation drive.','社区志愿者组织维修和募捐，对图书馆重新开放起了关键作用。','Community volunteers were instrumental in reopening the library / after they organized repairs / and a donation drive.','be instrumental in 表示对某结果起重要作用；in 后接动名词 reopening。','志愿者的维修和募捐促成了重新开放。'),C('instrumental.s2','音乐与演奏','The instrumental version of the song replaced the singer’s voice with strings, piano, and percussion.','这首歌的器乐版用弦乐、钢琴和打击乐取代了人声。','The instrumental version of the song / replaced the singer’s voice / with strings, piano, and percussion.','instrumental 修饰 version，表示没有歌声、由乐器演奏；with 列出演奏乐器。','歌曲由器乐而非人声呈现。')],M('Volunteers were instrumental in reopening the library, meaning they had no role in the work or result.','Volunteers were instrumental in reopening the library, meaning their work helped make it happen.','be instrumental in 表示起重要作用，不是毫无关系。','meaning'),[Q('instrumental',1,1,'To be instrumental in an outcome is to?','help make it happen','have no effect on it','be impossible to measure','s1 指发挥关键作用。'),Q('instrumental',2,2,'An instrumental version of a song features?','musical instruments rather than a sung vocal','only spoken dialogue','a legal injunction','s2 指器乐演奏的。'),Q('instrumental',3,1,'Why were volunteers instrumental in reopening the library?','they organized repairs and donations','they had no connection to the library','they closed the building permanently','志愿者的工作促成重新开放。'),Q('instrumental',4,2,'Which performance is instrumental?','a melody played on piano and strings without a singer','a solo speech with no music','a reading of a court order','由乐器演奏而无人声的是器乐版。')]);
P('instrumentalist','Instrumentalist 由 instrument 加 -alist 构成，可指演奏乐器而非演唱的音乐家，也可指认为理论应按实际用途评估的人。',[C('instrumentalist.s1','音乐家与演奏','The instrumentalist performed the flute solo while the choir waited for its entrance in the next movement.','合唱团等待下一乐章入场时，这位乐器演奏者演奏了长笛独奏。','The instrumentalist performed the flute solo / while the choir waited / for its entrance in the next movement.','instrumentalist 指演奏乐器的音乐家；while 表示合唱团等待期间发生的演奏。','长笛独奏由乐器演奏者完成。'),C('instrumentalist.s2','哲学与理论','As an instrumentalist, the philosopher judged the model by its predictive usefulness rather than claiming it revealed ultimate reality.','作为工具主义者，这位哲学家根据模型的预测用途来评价它，而不宣称它揭示了终极实在。','As an instrumentalist / the philosopher judged the model by its predictive usefulness / rather than claiming it revealed ultimate reality.','instrumentalist 在哲学中指重视理论实用效果的人；rather than 对比两种评价标准。','模型按预测用途评价，符合工具主义观点。')],M('The instrumentalist in the philosophy seminar judged the theory only by whether it revealed ultimate reality, not by its usefulness.','The realist in the philosophy seminar judged the theory by whether it revealed ultimate reality.','只以揭示实在为标准与工具主义重视实用性的观点相反。','word-choice'),[Q('instrumentalist',1,1,'A musical instrumentalist is a musician who?','plays an instrument rather than singing','writes only legal orders','conducts a public opinion survey','s1 指乐器演奏者。'),Q('instrumentalist',2,2,'A philosophical instrumentalist may judge a theory by?','its practical usefulness','whether it is a musical instrument','the number of people who sing it','s2 重视理论实用效果。'),Q('instrumentalist',3,1,'Who is an instrumentalist in an orchestra?','a musician playing the flute','a singer performing a solo','a person measuring the stage','长笛演奏者是 instrumentalist。'),Q('instrumentalist',4,2,'Why did the philosopher call the model useful?','it predicted outcomes even without claiming ultimate truth','it was played by a string section','it had no practical purpose','工具主义者可看重模型的预测用途。')]);
P('insubordinate','Insubordinate 由 in- 与 subordinate“服从的”构成，形容不愿服从负责人命令、抗命的。',C('insubordinate.s1','职责与服从','The supervisor documented the insubordinate refusal to follow the laboratory safety order and reassigned the task.','主管记录了对实验室安全命令的抗拒，并重新分派了任务。','The supervisor documented the insubordinate refusal / to follow the laboratory safety order / and reassigned the task.','insubordinate 修饰 refusal，表示不服从上级指令；to follow 说明拒绝内容。','明确拒绝遵守安全命令属于抗命。'),M('The worker was insubordinate because she followed every safety order and asked permission before acting.','The worker was obedient because she followed every safety order and asked permission before acting.','遵守命令与抗命相反。','word-choice'),[Q('insubordinate',1,1,'An insubordinate employee is?','unwilling to obey someone in charge','always eager to follow instructions','in need of a stronger light bulb','insubordinate 指不服从。'),Q('insubordinate',2,1,'Why was the refusal insubordinate?','it rejected a supervisor’s safety order','it followed the order exactly','it asked for clarification politely','抗拒负责人命令构成不服从。'),Q('insubordinate',3,1,'Which action is insubordinate?','deliberately refusing a lawful instruction from a supervisor','asking a respectful question about a task','following a safety procedure','故意拒绝上级合理指令是抗命。'),Q('insubordinate',4,1,'Insubordinate is the opposite of?','obedient','inquisitive','insipid','obedient 意为服从的。')]);
P('insufferable','Insufferable 由 in- 与 sufferable“可忍受的”构成，形容极其令人不快、傲慢或烦人的人和事。',C('insufferable.s1','行为与烦扰','The guests found the host’s insufferable boasting exhausting because he interrupted every conversation to praise himself.','客人觉得主人令人难以忍受的自夸很累人，因为他总打断谈话来夸耀自己。','The guests found the host’s insufferable boasting exhausting / because he interrupted every conversation / to praise himself.','insufferable 修饰 boasting，表示极其令人讨厌；because 解释客人反感的原因。','反复打断众人夸自己令人厌烦。'),M('The guests found the host insufferable because he listened politely and never interrupted anyone.','The guests found the host considerate because he listened politely and never interrupted anyone.','礼貌倾听、不打断他人并非令人难以忍受。','word-choice'),[Q('insufferable',1,1,'An insufferable person is?','extremely unpleasant or annoying','easy to tolerate and considerate','a person who installs software','insufferable 表示难以忍受。'),Q('insufferable',2,1,'Why was the host’s boasting insufferable?','he interrupted every conversation to praise himself','he listened patiently and shared credit','he arrived slightly late once','自夸且频繁打断使人厌烦。'),Q('insufferable',3,1,'Which behavior may be insufferable?','constantly bragging and talking over everyone','listening respectfully to other speakers','offering a brief apology','持续自夸并压过别人说话令人难以忍受。'),Q('insufferable',4,1,'Insufferable is closest in meaning to?','unbearable','informed','infrequent','insufferable 意为不可忍受的。')]);
P('insular','Insular 来自拉丁语 insularis、源自 insula“岛屿”，可指岛屿的，也可比喻思想狭隘、不愿接纳外界观点。',[C('insular.s1','岛屿与地理','The insular community relied on boats for supplies because the small island had no bridge to the mainland.','这个岛屿社区依靠船只运送物资，因为小岛没有通往大陆的桥。','The insular community relied on boats for supplies / because the small island / had no bridge to the mainland.','insular 描写岛屿上的社区；because 引出交通条件。','社区位于小岛上，交通依赖船只。'),C('insular.s2','思想与开放性','The committee’s insular outlook led it to dismiss useful ideas from neighboring regions without considering them.','委员会狭隘的观念使它不加考虑就否定了邻近地区的有用想法。','The committee’s insular outlook led it to dismiss useful ideas / from neighboring regions / without considering them.','insular 比喻思想封闭、排斥外来观点；led to 表示其结果。','未评估就拒绝外地建议体现狭隘。')],M('The committee had an insular outlook because it eagerly studied and adopted useful ideas from outside its group.','The committee had an open outlook because it studied and adopted useful ideas from outside its group.','积极接纳外部想法与狭隘封闭相反。','word-choice'),[Q('insular',1,1,'An insular village is?','located on an island','located far inside a desert','a system of heating equipment','s1 指岛屿的。'),Q('insular',2,2,'An insular outlook is?','narrow and unwilling to consider outside ideas','open to different experiences','a sudden reaction without thought','s2 比喻思想狭隘。'),Q('insular',3,1,'Why did an insular community rely on boats?','it lived on an island without a bridge','it lived in a landlocked city','it had no water nearby','岛屿居民通过船只运输。'),Q('insular',4,2,'Which committee seems insular?','one dismissing outside proposals without hearing them','one considering ideas from neighboring groups','one inviting a public review','拒绝听取外来意见体现封闭。')]);
P('insularity','Insularity 由 insular 加 -ity 构成，可指思想封闭、忽略外部经验，也可指四面环海的岛屿状态或由此形成的生活条件。',[C('insularity.s1','思想与视野','The report warned that the club’s insularity was limiting its membership because it ignored people from nearby neighborhoods.','报告警告，俱乐部的封闭狭隘正在限制会员增长，因为它忽视了邻近社区的人。','The report warned that the club’s insularity was limiting its membership / because it ignored people / from nearby neighborhoods.','insularity 指思想狭隘、忽略外界经验；because 说明其影响。','拒绝邻近社区成员使组织视野封闭。'),C('insularity.s2','岛屿地理','The island’s insularity shaped local transport, as residents depended on ferries to reach the mainland.','岛屿四面环海的地理状态影响了当地交通，居民依靠渡轮前往大陆。','The island’s insularity shaped local transport / as residents depended on ferries / to reach the mainland.','insularity 可指岛屿状态或与海隔开的生活条件；as 引出交通影响。','居民必须乘渡轮离岛，体现地理隔绝。')],M('The club’s insularity increased because it welcomed new members and regularly listened to outside groups.','The club’s openness increased because it welcomed new members and listened to outside groups.','积极欢迎外人说明开放，而非封闭狭隘。','word-choice'),[Q('insularity',1,1,'A group’s insularity is?','narrowness that ignores outside experience','its ability to welcome every new idea','the act of installing equipment','s1 指思想封闭。'),Q('insularity',2,2,'An island’s insularity refers to?','its condition of being surrounded by sea','its lack of confidence in public speaking','its use of an inbuilt heater','s2 指岛屿与外界隔海的状态。'),Q('insularity',3,1,'Why did the club’s insularity limit membership?','it ignored people from nearby neighborhoods','it invited them to join','it expanded its outreach program','忽视邻近社区成员限制了招新。'),Q('insularity',4,2,'How can insularity shape island transport?','residents may rely on ferries to reach the mainland','residents can always walk across a bridge','it eliminates the need for transportation','隔海地理使居民依赖渡轮。')]);
P('insulating','Insulating 由 insulate 加 -ing 构成，作形容词表示能够阻止热、电流或噪声通过的。',C('insulating.s1','材料与防护','The electrician wrapped the exposed cable in insulating material before reconnecting it to the control panel.','电工在把裸露电缆重新接到控制面板前，用绝缘材料包裹了它。','The electrician wrapped the exposed cable in insulating material / before reconnecting it / to the control panel.','insulating 修饰 material，表示能阻止电流通过；before 标出安全操作顺序。','绝缘材料包住电缆以防电流外泄。'),M('The electrician used insulating material that allowed current to pass freely through the exposed cable.','The electrician used conductive material that allowed current to pass freely through the cable.','让电流自由通过的材料是导电的，不是 insulating。','confusable'),[Q('insulating',1,1,'Insulating material helps prevent the passage of?','heat, electricity, or sound','only written information','a person’s natural instinct','insulating 表示隔热、绝缘或隔音的。'),Q('insulating',2,1,'Why wrap a cable in insulating material?','to reduce the chance of electric current passing outward','to make current flow through the outer surface','to measure its length in inches','绝缘层阻止电流通过。'),Q('insulating',3,1,'Which item is insulating?','a layer that keeps heat from passing through a wall','a bare metal wire designed to conduct current','a speaker producing loud noise','隔热层能够阻止热量传递。'),Q('insulating',4,1,'Insulating is related to which verb?','insulate','instigate','insist','insulating 由 insulate 派生。')]);
P('insulation','Insulation 由 insulate 加 -ion 构成，可指阻隔热、电或声音的材料层，也可指与有害接触或影响隔离的状态。',[C('insulation.s1','建筑与材料','The attic insulation kept the upstairs rooms warmer by slowing heat loss through the roof.','阁楼的隔热层减缓了热量从屋顶散失，使楼上房间更暖和。','The attic insulation kept the upstairs rooms warmer / by slowing heat loss / through the roof.','insulation 指减少热传递的材料层；by 引出保温原理。','隔热材料减缓热量外流。'),C('insulation.s2','隔离与影响','The journalist sought insulation from political pressure by asking an independent editor to review the findings.','记者请独立编辑审阅调查结果，以隔绝政治压力的影响。','The journalist sought insulation from political pressure / by asking an independent editor / to review the findings.','insulation 可指与有害影响隔离的状态；from 标出被隔离的压力。','独立审阅保护报道免受政治干预。')],M('The attic insulation increased heat loss through the roof and made the rooms colder.','The attic insulation reduced heat loss through the roof and kept the rooms warmer.','隔热层减少热量散失，不会增加热损失。','word-choice'),[Q('insulation',1,1,'Attic insulation is?','material that reduces heat passing through the roof','a device that makes heat escape faster','a legal order','s1 指隔热材料或层。'),Q('insulation',2,2,'A journalist may seek insulation from political pressure to?','keep that influence from affecting the review','make the pressure stronger','install a new roof','s2 指与有害影响隔离。'),Q('insulation',3,1,'Why did the upstairs rooms stay warmer?','insulation slowed heat loss through the roof','the insulation increased heat loss','the roof had no covering','隔热层使热量不易散失。'),Q('insulation',4,2,'Which choice provides insulation from outside influence?','independent review of findings','letting the interested party control every review','removing all evidence','独立审查可避免外部施压。')]);
P('insulator','Insulator 由 insulate 加 -or 构成，指阻止热或电通过的物质、部件或绝缘子。',C('insulator.s1','电气与安全','A ceramic insulator separated the high-voltage wire from the metal support on the utility pole.','陶瓷绝缘子把高压电线与电线杆上的金属支架隔开。','A ceramic insulator separated the high-voltage wire / from the metal support / on the utility pole.','insulator 指阻止电流传递的部件；from 标出它隔开的两种材料。','陶瓷部件防止高压电线与金属支架导通。'),M('The ceramic insulator connected the live wire directly to the metal support and conducted current between them.','The ceramic conductor connected the live wire directly to the metal support and carried current between them.','导电材料让电流通过，不是 insulator。','confusable'),[Q('insulator',1,1,'An electrical insulator?','stops current from passing through a material or fitting','carries current freely between wires','measures temperature only','insulator 指阻止电流传导的部件。'),Q('insulator',2,1,'Why was ceramic used on the utility pole?','it separated the high-voltage wire from metal','it encouraged current to flow into the support','it provided an in-depth report','陶瓷绝缘子隔开电线与金属支架。'),Q('insulator',3,1,'Which object is an insulator?','a fitting that prevents heat or electricity from passing','a copper wire carrying current','a glass of water used for drinking','阻止热或电通过的部件属于绝缘体。'),Q('insulator',4,1,'Insulator is the noun for something that?','insulates','instills an attitude','inaugurates a building','insulator 指执行隔绝作用的物质或部件。')]);
P('insulin','Insulin 名称源自拉丁语 insula“岛”，因胰腺胰岛细胞产生这种激素；它帮助身体利用葡萄糖。',C('insulin.s1','生理与激素','The nurse explained that insulin is a hormone from the pancreas that helps the body use glucose.','护士解释说，胰岛素是胰腺产生的一种激素，能帮助身体利用葡萄糖。','The nurse explained / that insulin is a hormone from the pancreas / that helps the body use glucose.','insulin 指胰腺激素；第二个 that 从句说明其生理作用。','激素来源与帮助利用葡萄糖均符合定义。'),M('Insulin is a hormone from the pancreas that prevents the body from using glucose.','Insulin is a hormone from the pancreas that helps the body use glucose.','胰岛素帮助身体利用葡萄糖，而不是阻止利用。','word-choice'),[Q('insulin',1,1,'Insulin is?','a hormone produced by the pancreas','a mineral used to make an ingot','a sound below human hearing','insulin 是胰腺激素。'),Q('insulin',2,1,'What does insulin help the body do?','use glucose','hear infrasound','install a computer program','胰岛素帮助身体利用葡萄糖。'),Q('insulin',3,1,'Where is insulin produced?','in the pancreas','in the inner ear','in a metal foundry','胰腺产生胰岛素。'),Q('insulin',4,1,'Insulin is most closely associated with?','hormone regulation of glucose use','island transport by ferry','protection from political pressure','胰岛素参与葡萄糖代谢调节。')]);
P('insure','Insure 经中古英语与古法语 asseurer“使有保障”演变，现代常指为人或财物安排保险。',C('insure.s1','保险与财产','The family insured the house against flood damage after moving beside the river.','搬到河边后，这家人为房屋投保，以防洪水造成损失。','The family insured the house against flood damage / after moving beside the river.','insure property against risk 表示为财物投保以防某种损失；after 引出投保原因。','房屋保险针对洪灾风险提供保障。'),M('The family insured the house by leaving it without any insurance policy or financial protection.','The family left the house uninsured by arranging no insurance policy or financial protection.','没有保单或保障表示未投保。','word-choice'),[Q('insure',1,1,'To insure a house is to?','arrange insurance protection for it','make certain that a door is closed','install a new roof without a policy','insure 指安排保险。'),Q('insure',2,1,'Why did the family insure the house against floods?','they wanted insurance protection from possible damage','they wanted to guarantee that no flood could occur','they wanted to measure the river in inches','投保用于应对可能的洪水损失。'),Q('insure',3,1,'Which sentence uses insure in the insurance sense?','They insured the boat before taking it to sea.','They insured that the light was switched off.','They insured the answer by repeating it.','第一句是为船只购买保险。'),Q('insure',4,1,'Insure is used here to mean?','arrange insurance for someone or something','make an outcome certain','inspire someone to act','本词条的 insure 指投保。')]);

})();
